public static String join(Object[] array, char separator, int startIndex, int endIndex) {
    if (array == null) {
        return null;
    }
    int arraySize = array.length;

    // If the array is empty, there is nothing to join.
    if (arraySize == 0) {
        return EMPTY;
    }

    // Defensively adjust indices to be within the valid bounds of the array.
    // A negative startIndex is treated as 0.
    if (startIndex < 0) {
        startIndex = 0;
    }
    // An endIndex greater than the array size is treated as the array size.
    if (endIndex > arraySize) {
        endIndex = arraySize;
    }

    // Calculate the number of items to join based on the adjusted, safe indices.
    // If the resulting range is empty or invalid, return an empty string.
    int numberOfItems = endIndex - startIndex;
    if (numberOfItems <= 0) {
        return EMPTY;
    }

    // Initialize StringBuilder with a safer, more general capacity estimate
    // to reduce the likelihood of internal array resizing.
    // (16 is a common default capacity for string-like objects).
    StringBuilder buf = new StringBuilder(numberOfItems * 16);

    // Loop through the safe, validated range.
    for (int i = startIndex; i < endIndex; i++) {
        // Append separator before each element except the first.
        if (i > startIndex) {
            buf.append(separator);
        }
        // Append the string representation of non-null elements.
        if (array[i] != null) {
            buf.append(array[i]);
        }
    }
    return buf.toString();
}

public static boolean containsIgnoreCase(String str, String searchStr) {
    // 1. Handle null inputs, which is a common failure case.
    if (str == null || searchStr == null) {
        return false;
    }

    // 2. An empty search string is always considered to be contained.
    // This matches the behavior of java.lang.String.contains("").
    if (searchStr.isEmpty()) {
        return true;
    }

    // 3. Pre-calculate lengths for efficiency and clarity.
    final int searchStrLen = searchStr.length();
    final int strLen = str.length();

    // 4. A string cannot contain a search string that is longer than itself.
    if (searchStrLen > strLen) {
        return false;
    }

    // 5. Iterate through the string to find a matching region.
    // The loop limit ensures we don't check past the point where a match is possible.
    for (int i = 0; i <= strLen - searchStrLen; i++) {
        // Use regionMatches for a locale-independent, case-insensitive comparison
        // without creating new String objects.
        if (str.regionMatches(true, i, searchStr, 0, searchStrLen)) {
            return true;
        }
    }

    // 6. If the loop completes, no match was found.
    return false;
}

protected int findWrapPos(String text, int width, int startPos) {
        // 1. Input validation for robustness
        if (text == null || width <= 0) {
            return -1;
        }
        if (startPos < 0 || startPos >= text.length()) {
            return -1;
        }

        final int wrapLimit = startPos + width;

        // 2. Prioritize explicit newlines within the wrap limit
        int newlinePos = text.indexOf('\n', startPos);
        if (newlinePos != -1 && newlinePos < wrapLimit) {
            return newlinePos + 1;
        }

        // 3. If the rest of the string fits, we are done
        if (wrapLimit >= text.length()) {
            return -1;
        }

        // 4. Search backwards for a whitespace character for a clean word break.
        // Start search from the wrap limit, ensuring we don't go out of bounds.
        int pos = Math.min(wrapLimit, text.length() - 1);
        while (pos > startPos && !Character.isWhitespace(text.charAt(pos))) {
            pos--;
        }

        // If a whitespace was found after the start position, break after it.
        if (pos > startPos) {
            return pos + 1;
        }

        // 5. If no whitespace was found (long word), perform a hard wrap at the limit.
        // The next line will start exactly at the wrap limit.
        return wrapLimit;
    }

public List<Object> getValues(final Option option, final List<Object> defaultValues) {
    // 1. Robustness: Handle null input gracefully.
    if (option == null) {
        return Collections.emptyList();
    }

    // Define a variable to hold the list from the highest-priority source.
    // Use generics for type safety.
    List<Object> foundValues = null;

    // 2. Logic: Prioritized search for values.
    // Priority 1: Check for values explicitly provided on the command line.
    @SuppressWarnings("unchecked") // Assuming 'values' map stores List<Object>
    List<Object> explicitValues = (List<Object>) values.get(option);
    if (explicitValues != null && !explicitValues.isEmpty()) {
        foundValues = explicitValues;
    }
    // Priority 2: Fallback to the parameter-provided default values.
    else if (defaultValues != null && !defaultValues.isEmpty()) {
        foundValues = defaultValues;
    }
    // Priority 3: Fallback to the instance's pre-configured default values.
    else {
        @SuppressWarnings("unchecked") // Assuming 'defaultValues' map stores List<Object>
        List<Object> internalDefaults = (List<Object>) this.defaultValues.get(option);
        if (internalDefaults != null && !internalDefaults.isEmpty()) {
            foundValues = internalDefaults;
        }
    }

    // 3. Robustness: Return a safe result.
    // If no values were found, return an immutable empty list.
    if (foundValues == null) {
        return Collections.emptyList();
    }

    // Otherwise, return a new ArrayList (a defensive copy) to prevent aliasing.
    return new ArrayList<>(foundValues);
}

public boolean hasOption(String opt)
{
    // An option name cannot be null or empty. By returning false, we adhere
    // to a clear and safe contract: if the identifier is invalid, the
    // option cannot be present.
    if (opt == null || opt.isEmpty()) {
        return false;
    }

    return options.containsKey(opt);
}

public Option create(String opt) throws IllegalArgumentException {
        // 1. Add robust input validation.
        if (opt == null) {
            throw new IllegalArgumentException("Short option name must not be null.");
        }

        // 2. Create the base Option instance.
        // The constructor using the description is a reasonable starting point.
        Option option = new Option(opt, this.description);

        // 3. Set properties from the builder's instance fields.
        option.setLongOpt(this.longOpt);
        option.setRequired(this.required);
        option.setOptionalArg(this.optionalArg);
        option.setArgs(this.numberOfArgs);
        option.setType(this.type);
        option.setValueSeparator(this.valueSeparator);
        option.setArgName(this.argName);

        // 4. Remove the call to reset(). It is no longer needed because the builder
        // is an instance that will be garbage collected after use, ensuring no
        // state leaks between creations.

        // 5. Return the fully configured Option.
        return option;
    }

protected StringBuffer renderWrappedText(StringBuffer sb, int width, 
                                             int nextLineTabStop, String text)
    {
        // 1. Robustness: Handle null or empty input gracefully.
        if (text == null || text.isEmpty()) {
            return sb;
        }

        // 2. Robustness: Validate dimensional parameters to prevent exceptions/infinite loops.
        if (width <= 0) {
            // Cannot wrap to a non-positive width, return buffer as-is.
            return sb;
        }
        if (nextLineTabStop >= width) {
            // Hanging indent cannot be >= width, this would lead to infinite loops.
            throw new IllegalArgumentException("nextLineTabStop must be less than width.");
        }

        String remainingText = text;
        final String padding = createPadding(nextLineTabStop);
        boolean firstLine = true;

        // 3. Refactored Logic: Process the text in a single, clear loop.
        while (remainingText.length() > 0) {
            String lineToProcess;
            int searchStartPos;

            if (firstLine) {
                lineToProcess = remainingText;
                searchStartPos = 0;
            } else {
                // Trim leading whitespace from the remainder before adding our own padding.
                lineToProcess = padding + remainingText.trim();
                searchStartPos = nextLineTabStop;
            }

            int wrapPos = findWrapPos(lineToProcess, width, searchStartPos);

            // Case 1: No wrap position found.
            if (wrapPos == -1) {
                // This means either the line fits, or it contains a word too long to wrap.
                if (lineToProcess.length() <= width) {
                    // The entire remaining text fits on this line. Append and finish.
                    sb.append(rtrim(lineToProcess));
                    break; // Exit loop
                } else {
                    // 4. Logical Fix: Handle long words by hard-breaking the line at `width`.
                    sb.append(rtrim(lineToProcess.substring(0, width))).append(defaultNewLine);
                    remainingText = lineToProcess.substring(width);
                }
            }
            // Case 2: A valid wrap position was found.
            else {
                sb.append(rtrim(lineToProcess.substring(0, wrapPos))).append(defaultNewLine);
                remainingText = lineToProcess.substring(wrapPos);
            }

            firstLine = false;
        }

        return sb;
    }

public boolean isDoubleMetaphoneEqual(final String value1, final String value2, final boolean alternate) {
    /*
     * The original implementation would throw a NullPointerException if value1 was null.
     * This corrected version uses java.util.Objects.equals() to perform a null-safe
     * comparison of the generated metaphone codes. This ensures that the method
     * returns a boolean value under all input conditions, preventing runtime exceptions.
     */
    return Objects.equals(
        doubleMetaphone(value1, alternate),
        doubleMetaphone(value2, alternate)
    );
}

