public static boolean equals(final CharSequence cs1, final CharSequence cs2) {
    // Correct: Identity check is the fastest and handles (null, null).
    if (cs1 == cs2) {
        return true;
    }
    // Correct: If one is null, they aren't equal.
    if (cs1 == null || cs2 == null) {
        return false;
    }
    // Correct: Optimization for the common String case.
    if (cs1 instanceof String && cs2 instanceof String) {
        return cs1.equals(cs2);
    }

    // CRITICAL FIX: Add a length check before comparing characters.
    // If lengths differ, the sequences cannot be equal. This also prevents
    // the IndexOutOfBoundsException that occurred in the original code.
    if (cs1.length() != cs2.length()) {
        return false;
    }

    // CRITICAL FIX: Use the correct length for the comparison.
    // Since we have now confirmed the lengths are equal, we can safely use
    // cs1.length() (or cs2.length()). The original code's use of Math.max()
    // was the source of the bug.
    return CharSequenceUtils.regionMatches(cs1, false, 0, cs2, 0, cs1.length());
}

@Override
public int read(byte b[], int offset, int len) throws IOException {
    // 1. Standard parameter validation. This was correct in the original.
    if (b == null) {
        throw new NullPointerException("Destination buffer cannot be null.");
    }
    if (offset < 0 || len < 0) {
        throw new IndexOutOfBoundsException("Offset and length must be non-negative.");
    }
    if (offset > b.length || offset + len > b.length) {
        throw new IndexOutOfBoundsException("Attempt to write outside of buffer bounds.");
    }
    if (len == 0) {
        return 0;
    }

    // 2. Loop until data is read or EOF is reached, fulfilling the InputStream contract.
    int readLen = 0;
    while (readLen == 0) {
        // 3. If the codec's internal buffer is empty, read from the underlying stream.
        if (!base64.hasData()) {
            byte[] buf = new byte[doEncode ? 4096 : 8192];
            int c = in.read(buf);

            // 4. Feed the newly read data (or EOF signal) to the Base64 codec.
            // The Base64 class is expected to handle c = -1 as an EOF marker.
            if (doEncode) {
                base64.encode(buf, 0, c);
            } else {
                base64.decode(buf, 0, c);
            }
        }

        // 5. Attempt to fill the user's buffer with processed data.
        // This call will return >0 if data was written, 0 if more input is needed,
        // or -1 if the stream is fully exhausted.
        readLen = base64.readResults(b, offset, len);

        // 6. If readResults returns 0, the loop continues, forcing another read from
        // the underlying stream until output is produced or the stream ends.
        // If readResults returns -1, it signals EOF, so we exit the loop.
        if (readLen == -1) {
            break;
        }
    }
    return readLen;
}

public static String encodeBase64String(byte[] binaryData) {
        // 1. Robustness: Add a null check to handle null input gracefully
        // and prevent NullPointerException. Returning null for null input is a
        // common and predictable contract.
        if (binaryData == null) {
            return null;
        }

        // 2. Corrected Logic: Use the non-chunked version of encodeBase64.
        // This aligns the method's behavior with its generic name and the
        // common expectation of developers.
        byte[] encodedBytes = encodeBase64(binaryData);

        // The conversion to a UTF-8 string remains correct.
        return StringUtils.newStringUtf8(encodedBytes);
    }

@Override
    public int read(byte b[], int offset, int len) throws IOException {
        if (b == null) {
            throw new NullPointerException("Destination byte array cannot be null.");
        } else if (offset < 0 || len < 0) {
            throw new IndexOutOfBoundsException("Offset and length must be non-negative: offset=" + offset + ", len=" + len);
        } else if (offset > b.length || offset + len > b.length) {
            throw new IndexOutOfBoundsException(
                "Read request exceeds destination buffer bounds: offset=" + offset + ", len=" + len + ", buffer size=" + b.length
            );
        } else if (len == 0) {
            return 0;
        } else {
            int readLen = 0;
            /*
             Rationale for while-loop on (readLen == 0):
             -----
             Base64.readResults() usually returns > 0 or EOF (-1).  In the
             rare case where it returns 0, we just keep trying.

             This is essentially an undocumented contract for InputStream
             implementors that want their code to work properly with
             java.io.InputStreamReader, since the latter hates it when
             InputStream.read(byte[]) returns a zero.  Unfortunately our
             readResults() call must return 0 if a large amount of the data
             being decoded was non-base64, so this while-loop enables proper
             interop with InputStreamReader for that scenario.
             -----
             This is a fix for CODEC-101
            */
            while (readLen == 0) {
                if (!base64.hasData()) {
                    byte[] buf = new byte[doEncode ? 4096 : 8192];
                    int c = in.read(buf);

                    // Corrected Optimization: If the read request is for the entire destination
                    // buffer, we can set it as the initial buffer in the codec to avoid an
                    // extra memory copy. This is only safe if the entire array is being used.
                    if (c > 0 && offset == 0 && len == b.length) {
                        base64.setInitialBuffer(b, offset, len);
                    }

                    if (doEncode) {
                        base64.encode(buf, 0, c);
                    } else {
                        base64.decode(buf, 0, c);
                    }
                }
                readLen = base64.readResults(b, offset, len);
            }
            return readLen;
        }
    }

public static byte[] encodeBase64(byte[] binaryData, boolean isChunked, boolean urlSafe, int maxResultSize) {
        if (binaryData == null || binaryData.length == 0) {
            return binaryData;
        }

        // Robustness Fix: Add validation for the maxResultSize parameter.
        if (maxResultSize < 0) {
            throw new IllegalArgumentException("maxResultSize must be a non-negative integer, but was: " + maxResultSize);
        }

        // Logical Fix: The length calculation must depend on the 'isChunked' flag
        // to be consistent with the encoding logic. A chunkSize of 0 signifies no chunking.
        final long estimatedLen = isChunked ?
                getEncodeLength(binaryData, MIME_CHUNK_SIZE, CHUNK_SEPARATOR) :
                getEncodeLength(binaryData, 0, null);

        if (estimatedLen > maxResultSize) {
            throw new IllegalArgumentException("Input array is too large. The estimated output array size (" +
                estimatedLen + ") exceeds the specified maximum size of " + maxResultSize);
        }

        // This part of the original logic was correct: it creates a Base64 encoder
        // that either chunks (by default) or doesn't (by setting lineLength to 0).
        final Base64 b64 = isChunked ? new Base64(urlSafe) : new Base64(0, CHUNK_SEPARATOR, urlSafe);
        return b64.encode(binaryData);
    }

@Override
public Iterator<CSVRecord> iterator() {
    return new Iterator<CSVRecord>() {
        private CSVRecord current;

        private CSVRecord getNextRecord() {
            try {
                return CSVParser.this.nextRecord();
            } catch (final IOException e) {
                // Wrap IOException in a runtime exception, as Iterator.next() is not
                // declared to throw checked exceptions.
                throw new IllegalStateException(
                        e.getClass().getSimpleName() + " reading next record: " + e.toString(), e);
            }
        }

        @Override
        public boolean hasNext() {
            if (CSVParser.this.isClosed()) {
                return false;
            }
            if (this.current == null) {
                this.current = this.getNextRecord();
            }
            return this.current != null;
        }

        @Override
        public CSVRecord next() {
            // First, ensure the parser is not closed.
            if (CSVParser.this.isClosed()) {
                throw new NoSuchElementException("CSVParser has been closed");
            }

            // Use hasNext() to ensure the 'current' record is populated and that we haven't
            // reached the end of the stream. This simplifies logic and avoids code duplication.
            if (!hasNext()) {
                throw new NoSuchElementException("No more CSV records available");
            }

            // Retrieve the pre-fetched record and clear the look-ahead buffer.
            final CSVRecord next = this.current;
            this.current = null;

            return next;
        }

        @Override
        public void remove() {
            throw new UnsupportedOperationException("The remove operation is not supported by this iterator.");
        }
    };
}

public String get(final String name) {
        // Validate that the requested header name is not null.
        if (name == null) {
            throw new IllegalArgumentException("Header name cannot be null.");
        }

        // Check if a header-to-index mapping exists.
        if (mapping == null) {
            throw new IllegalStateException(
                    "No header mapping was specified, the record values can't be accessed by name");
        }

        // Look up the index for the given header name.
        final Integer index = mapping.get(name);

        // If the index is found, return the value at that position; otherwise, return null.
        return index != null ? values[index.intValue()] : null;
    }

public Map<String, Integer> getHeaderMap() {
        // The original implementation returned a mutable copy.
        // This version returns an unmodifiable view of a copy, which is safer and clearer for the API user.
        return Collections.unmodifiableMap(new LinkedHashMap<>(this.headerMap));
    }

@Override
public void skipValue() throws IOException {
    // peek() will throw an IllegalStateException if the reader is closed or has no more tokens.
    JsonToken token = peek();

    // If the next token is a name, we must consume it to get to the actual value.
    if (token == JsonToken.NAME) {
        // nextName() consumes the name token and internally handles advancing the
        // iterator for the parent object.
        nextName();
    }

    // At this point, the top of the stack is guaranteed to be a value (JsonPrimitive,
    // JsonObject, or JsonArray). Popping it from the stack effectively "skips" it,
    // as this reader navigates an in-memory tree.
    popStack();

    // After consuming a value from a parent container (an object or array),
    // we must increment the index counter for that parent. The popStack() call
    // has already decremented stackSize, so stackSize-1 now points to the parent.
    // This logic mirrors the implementation of other next<Value>() methods in this class.
    // A check is added to prevent an exception if the stack is empty.
    if (stackSize > 0) {
        pathIndices[stackSize - 1]++;
    }
}

public static WildcardType subtypeOf(Type bound) {
  // Fail fast if the bound is null to prevent creating an invalid type.
  if (bound == null) {
    throw new NullPointerException("bound == null");
  }
  Type[] upperBounds = new Type[] { bound };
  return new WildcardTypeImpl(upperBounds, EMPTY_TYPE_ARRAY);
}

public static WildcardType supertypeOf(Type bound) {
    if (bound == null) {
      throw new NullPointerException("bound == null");
    }
    // Wildcard bounds must be reference types, not primitives.
    checkNotPrimitive(bound);
    return new WildcardTypeImpl(new Type[] { Object.class }, new Type[] { bound });
  }

public JsonWriter value(double value) throws IOException {
    writeDeferredName();
    // The check for non-finite numbers must only be enforced when not in lenient mode.
    if (!lenient && (Double.isNaN(value) || Double.isInfinite(value))) {
      throw new IllegalArgumentException("Numeric values must be finite, but was " + value);
    }
    beforeValue();
    out.append(Double.toString(value));
    return this;
}

