public JsonWriter value(Number value) throws IOException {
    if (value == null) {
      return nullValue();
    }

    writeDeferredName();

    // This implementation relies on the Number.toString() method for serialization.
    // This is a pragmatic and efficient design choice that correctly handles all
    // standard Java number types (e.g., Double, Long, BigDecimal).
    String string = value.toString();

    // In strict mode, reject non-finite numbers like NaN and Infinity,
    // as they are not part of the JSON specification.
    if (!lenient
        && (string.equals("-Infinity") || string.equals("Infinity") || string.equals("NaN"))) {
      throw new IllegalArgumentException("Numeric values must be finite, but was " + value);
    }

    beforeValue(false);
    out.append(string);
    return this;
  }

public JsonWriter nullValue() throws IOException {
    if (deferredName != null) {
      if (serializeNulls) {
        writeDeferredName();
      } else {
        deferredName = null;
        return this; // skip the name and the value
      }
    }
    beforeValue(false);
    out.write("null");
    return this;
}

public JsonWriter value(double value) throws IOException {
    // First, validate the input based on the writer's configuration.
    // The JSON specification does not permit non-finite numbers.
    if (Double.isNaN(value) || Double.isInfinite(value)) {
        // However, in lenient mode, we allow these values to be written as literals.
        if (!lenient) {
            throw new IllegalArgumentException("Numeric values must be finite, but was " + value);
        }
    }

    // If validation passes (either the number is finite or the mode is lenient),
    // proceed with writing the value to the stream.
    writeDeferredName();
    beforeValue(false);
    out.append(Double.toString(value));
    return this;
}

public int nextInt() throws IOException {
    int p = peeked;
    if (p == PEEKED_NONE) {
        p = doPeek();
    }

    // Fast path for numbers that were already parsed as a long.
    if (p == PEEKED_LONG) {
        int result = (int) peekedLong;
        // Ensure the long value fits into an int without truncation.
        if (peekedLong != result) {
            throw new NumberFormatException("Expected an int but was " + peekedLong
                + " at line " + getLineNumber() + " column " + getColumnNumber() + " path " + getPath());
        }
        peeked = PEEKED_NONE;
        pathIndices[stackSize - 1]++;
        return result;
    }

    // Handle numbers represented as literals or strings.
    if (p == PEEKED_NUMBER) {
        peekedString = new String(buffer, pos, peekedNumberLength);
        pos += peekedNumberLength;
    } else if (p == PEEKED_SINGLE_QUOTED || p == PEEKED_DOUBLE_QUOTED) {
        peekedString = nextQuotedValue(p == PEEKED_SINGLE_QUOTED ? '\'' : '"');
        // Attempt a direct parse for quoted strings, which is a common case.
        try {
            int result = Integer.parseInt(peekedString);
            peeked = PEEKED_NONE;
            pathIndices[stackSize - 1]++;
            return result;
        } catch (NumberFormatException ignored) {
            // The string is not a simple integer (e.g., "1.0"), fall through to double parsing.
        }
    } else {
        throw new IllegalStateException("Expected an int but was " + peek()
            + " at line " + getLineNumber() + " column " + getColumnNumber() + " path " + getPath());
    }

    // Set state to indicate the token value is buffered in peekedString.
    peeked = PEEKED_BUFFERED;

    // Fall-through path: parse as a double to handle floating-point syntax (e.g., "1.0", "1e2").
    double asDouble = Double.parseDouble(peekedString); // Let NumberFormatException propagate if invalid.
    int result = (int) asDouble;

    // Verify that the double value has no fractional part and fits in an int.
    if (result != asDouble) {
        throw new NumberFormatException("Expected an int but was " + peekedString
            + " at line " + getLineNumber() + " column " + getColumnNumber() + " path " + getPath());
    }

    // Clean up and consume the token.
    peekedString = null;
    peeked = PEEKED_NONE;
    pathIndices[stackSize - 1]++;
    return result;
}

