public static Number createNumber(final String str) throws NumberFormatException {
        if (str == null) {
            return null;
        }
        if (StringUtils.isBlank(str)) {
            throw new NumberFormatException("A blank string is not a valid number");
        }

        // --- 1. Handle Hexadecimal Numbers ---
        if (str.startsWith("0x") || str.startsWith("0X") || str.startsWith("#")) {
            int hexDigits = str.length() - (str.startsWith("#") ? 1 : 2);
            if (hexDigits > 16) {
                return createBigInteger(str);
            }
            if (hexDigits > 8) {
                return createLong(str);
            }
            return createInteger(str);
        }
        if (str.startsWith("-0x") || str.startsWith("-0X")) {
            int hexDigits = str.length() - 3;
            if (hexDigits > 16) {
                return createBigInteger(str);
            }
            if (hexDigits > 8) {
                return createLong(str);
            }
            return createInteger(str);
        }

        final char lastChar = str.charAt(str.length() - 1);
        final String numericPart;
        final boolean hasDecimal = str.indexOf('.') != -1;
        final boolean hasExponent = str.indexOf('e') != -1 || str.indexOf('E') != -1;

        // --- 2. Handle Numbers with Type Suffixes (L, F, D) ---
        if (Character.isLetter(lastChar) && lastChar != 'e' && lastChar != 'E') {
            numericPart = str.substring(0, str.length() - 1);
            switch (lastChar) {
                case 'l':
                case 'L':
                    if (hasDecimal || hasExponent) {
                        throw new NumberFormatException(str + " is not a valid long number.");
                    }
                    // For longs, allow values too big for primitive long by returning BigInteger
                    try {
                        return createLong(numericPart);
                    } catch (final NumberFormatException e) {
                        return createBigInteger(numericPart);
                    }
                case 'f':
                case 'F':
                    // Strict: if user asks for a Float, give them a Float or an error.
                    return createFloat(numericPart);
                case 'd':
                case 'D':
                    // Strict: if user asks for a Double, give them a Double or an error.
                    return createDouble(numericPart);
                default:
                    throw new NumberFormatException(str + " is not a valid number.");
            }
        }

        // --- 3. Auto-detect Type for Numbers without Suffixes ---
        if (hasDecimal || hasExponent) {
            // It's a floating-point number. Prioritize precision.
            // Try Double first, as it's the most common floating-point type.
            try {
                final Double d = createDouble(str);
                // If the value is too large for a double, it will be Infinity.
                // In that case, fall back to BigDecimal for better precision.
                if (!d.isInfinite()) {
                    return d;
                }
            } catch (final NumberFormatException e) {
                // Let it fall through to BigDecimal for formats Double can't handle (e.g., "1.2.3")
            }
            // Fallback for very large/small numbers or when Double parsing fails.
            return createBigDecimal(str);
        } else {
            // It's an integer. Use the smallest type that can fit the value.
            try {
                return createInteger(str);
            } catch (final NumberFormatException e1) {
                try {
                    return createLong(str);
                } catch (final NumberFormatException e2) {
                    return createBigInteger(str);
                }
            }
        }
    }

public static String random(int count, int start, int end, boolean letters, boolean numbers,
                                char[] chars, Random random) {
        if (count == 0) {
            return "";
        }
        if (count < 0) {
            throw new IllegalArgumentException("Requested random string length " + count + " is less than 0.");
        }
        if (chars != null && chars.length == 0) {
            throw new IllegalArgumentException("The chars array must not be empty.");
        }

        int effectiveStart = start;
        int effectiveEnd = end;

        if (effectiveStart == 0 && effectiveEnd == 0) {
            if (chars != null) {
                effectiveEnd = chars.length;
            } else {
                // Default to the full Unicode range to allow for any letter/number.
                // The filters will handle selection.
                effectiveEnd = Character.MAX_CODE_POINT + 1;
                effectiveStart = 0;
            }
        } else if (effectiveEnd < effectiveStart) {
            throw new IllegalArgumentException(
                "Parameter 'end' (" + effectiveEnd + ") must be greater than or equal to 'start' (" + effectiveStart + ")."
            );
        }

        final int[] codePoints = new int[count];
        final int gap = effectiveEnd - effectiveStart;
        int i = 0;

        while (i < count) {
            int retries = 0;
            while (true) {
                if (retries++ > MAX_RETRIES) {
                    throw new IllegalArgumentException(
                        "Unable to generate a random character matching the specified criteria " +
                        "after " + MAX_RETRIES + " attempts. The character source may be too small " +
                        "or incompatible with the filters."
                    );
                }

                int codePoint;
                if (chars == null) {
                    // Generate a code point within the specified range
                    codePoint = random.nextInt(gap) + effectiveStart;
                } else {
                    // Select a character from the array and get its code point
                    char ch = chars[random.nextInt(gap) + effectiveStart];
                    codePoint = ch;
                }

                // Filter based on criteria
                final boolean isLetter = Character.isLetter(codePoint);
                final boolean isDigit = Character.isDigit(codePoint);

                if ((!letters && !numbers) || (letters && isLetter) || (numbers && isDigit)) {
                    // Check for and exclude unpaired surrogates when generating from a code point range
                    if (chars == null && (codePoint >= Character.MIN_SURROGATE && codePoint <= Character.MAX_SURROGATE)) {
                        continue; // This is a surrogate code point, retry to avoid generating an invalid string
                    }

                    // If a valid character is found, store it and move to the next position
                    codePoints[i] = codePoint;
                    i++;
                    break;
                }
            }
        }
        return new String(codePoints, 0, count);
    }

public static String random(int count, int start, int end, boolean letters, boolean numbers,
                                char[] chars, Random random) {
        if (count == 0) {
            return "";
        }
        if (count < 0) {
            throw new IllegalArgumentException("Requested random string length " + count + " is less than 0.");
        }
        if (random == null) {
            throw new IllegalArgumentException("The provided Random object must not be null.");
        }

        // Mode 1: Use the provided character set
        if (chars != null && chars.length > 0) {
            StringBuilder builder = new StringBuilder(count);
            for (int i = 0; i < count; i++) {
                builder.append(chars[random.nextInt(chars.length)]);
            }
            return builder.toString();
        }

        // Mode 2: Generate from a code point range with filtering
        if (end < start) {
            throw new IllegalArgumentException("The end value " + end + " must be greater than or equal to the start value " + start + ".");
        }

        // Set default range if not specified
        if (start == 0 && end == 0) {
            if (!letters && !numbers) {
                // Full Unicode range for valid code points
                end = Character.MAX_CODE_POINT + 1;
            } else {
                // A more sensible default range for letters/numbers
                end = 'z' + 1;
                start = ' ';
            }
        }

        StringBuilder builder = new StringBuilder(count);
        long range = (long) end - start;
        // Set a reasonable retry limit to prevent infinite loops
        int maxRetries = count * 20;
        int retries = 0;

        while (builder.codePointCount(0, builder.length()) < count) {
            if (retries++ > maxRetries) {
                throw new IllegalStateException(
                    "Could not generate random string of length " + count +
                    " with the given constraints. The specified range may not contain any valid characters."
                );
            }

            int codePoint;
            if (range > Integer.MAX_VALUE) {
                // Handle very large ranges that exceed Integer.MAX_VALUE
                long randomLong = (long) (random.nextDouble() * range);
                codePoint = (int) (start + randomLong);
            } else {
                codePoint = start + random.nextInt((int) range);
            }

            // Filter the generated code point
            boolean isLetter = Character.isLetter(codePoint);
            boolean isDigit = Character.isDigit(codePoint);

            if ((!letters || isLetter) && (!numbers || isDigit) && Character.isValidCodePoint(codePoint)) {
                // Avoid generating unpaired surrogates directly
                if (!Character.isSurrogate((char) codePoint)) {
                    builder.appendCodePoint(codePoint);
                }
            }
        }

        return builder.toString();
    }

public static Number createNumber(final String str) throws NumberFormatException {
        if (str == null) {
            return null;
        }
        if (StringUtils.isBlank(str)) {
            throw new NumberFormatException("A blank string is not a valid number");
        }
        // Special case for a BigDecimal parsing quirk
        if (str.startsWith("--")) {
            return null;
        }
        // Handle hexadecimal numbers
        if (str.startsWith("0x") || str.startsWith("-0x")) {
            try {
                // Integer.decode handles 0x and -0x
                return Integer.decode(str);
            } catch (final NumberFormatException e) {
                // Fallthrough to try a larger type
            }
            try {
                // Long.decode handles 0x and -0x
                return Long.decode(str);
            } catch (final NumberFormatException e) {
                // Fallthrough to BigInteger
            }
            // BigInteger constructor handles "0x" but not "-0x", so we strip the sign
            // and apply it after creation.
            if (str.startsWith("-0x")) {
                return new BigInteger(str.substring(3), 16).negate();
            }
            return new BigInteger(str.substring(2), 16);
        }

        final char lastChar = str.charAt(str.length() - 1);
        final String mant;
        final String dec;
        final String exp;

        final int decPos = str.indexOf('.');
        // CORRECTED: Use a clear and robust way to find the exponent separator
        final int expPos = Math.max(str.indexOf('e'), str.indexOf('E'));

        if (decPos > -1) {
            if (expPos > -1) {
                if (expPos < decPos || expPos > str.length()) {
                    throw new NumberFormatException(str + " is not a valid number.");
                }
                dec = str.substring(decPos + 1, expPos);
            } else {
                dec = str.substring(decPos + 1);
            }
            mant = str.substring(0, decPos);
        } else {
            if (expPos > -1) {
                if (expPos > str.length()) {
                    throw new NumberFormatException(str + " is not a valid number.");
                }
                mant = str.substring(0, expPos);
            } else {
                mant = str;
            }
            dec = null;
        }

        if (!Character.isDigit(lastChar) && lastChar != '.') {
            // String has a type qualifier suffix (L, F, D)
            if (expPos > -1 && expPos < str.length() - 1) {
                exp = str.substring(expPos + 1, str.length() - 1);
            } else {
                exp = null;
            }
            final String numeric = str.substring(0, str.length() - 1);
            final boolean allZeros = isAllZeros(mant) && isAllZeros(exp);

            switch (lastChar) {
                case 'l':
                case 'L':
                    if (dec == null && exp == null && (numeric.charAt(0) == '-' ? isDigits(numeric.substring(1)) : isDigits(numeric))) {
                        try {
                            return Long.valueOf(numeric);
                        } catch (final NumberFormatException e) {
                            // Value is too large for a Long, fall back to BigInteger
                            return new BigInteger(numeric);
                        }
                    }
                    throw new NumberFormatException(str + " is not a valid number.");

                case 'f':
                case 'F':
                    try {
                        final Float f = Float.valueOf(numeric);
                        // Avoid returning Float if it results in infinity or an imprecise zero
                        if (!(f.isInfinite() || (f.floatValue() == 0.0F && !allZeros))) {
                            return f;
                        }
                    } catch (final NumberFormatException e) {
                        // Fallthrough
                    }
                    // Fallthrough to Double

                case 'd':
                case 'D':
                    try {
                        final Double d = Double.valueOf(numeric);
                        // Avoid returning Double if it results in infinity or an imprecise zero
                        if (!(d.isInfinite() || (d.doubleValue() == 0.0D && !allZeros))) {
                            return d;
                        }
                    } catch (final NumberFormatException e) {
                        // Fallthrough
                    }
                    // Fallthrough to BigDecimal

                default: // Includes fallthrough from D
                    try {
                        return new BigDecimal(numeric);
                    } catch (final NumberFormatException e) {
                        // Should not happen, but rethrow to be safe
                        throw new NumberFormatException(str + " is not a valid number.");
                    }
            }
        } else {
            // No type qualifier suffix, determine type automatically
            if (expPos > -1 && expPos < str.length()) {
                exp = str.substring(expPos + 1);
            } else {
                exp = null;
            }

            if (dec == null && exp == null) {
                // Integer number
                try {
                    return Integer.valueOf(str);
                } catch (final NumberFormatException e) {
                    // Fallthrough
                }
                try {
                    return Long.valueOf(str);
                } catch (final NumberFormatException e) {
                    // Fallthrough
                }
                return new BigInteger(str);
            }

            // Floating point number
            final boolean allZeros = isAllZeros(mant) && isAllZeros(exp);
            try {
                final Float f = Float.valueOf(str);
                if (!(f.isInfinite() || (f.floatValue() == 0.0F && !allZeros))) {
                    return f;
                }
            } catch (final NumberFormatException e) {
                // Fallthrough
            }
            try {
                final Double d = Double.valueOf(str);
                if (!(d.isInfinite() || (d.doubleValue() == 0.0D && !allZeros))) {
                    return d;
                }
            } catch (final NumberFormatException e) {
                // Fallthrough
            }
            return new BigDecimal(str);
        }
    }

public static boolean equals(CharSequence cs1, CharSequence cs2) {
    // 1. Identity check: if they are the same object, they are equal.
    // This also correctly handles the case where both are null.
    if (cs1 == cs2) {
        return true;
    }

    // 2. Null check: if we reach here, they are not the same object.
    // If either is null, they can't be equal.
    if (cs1 == null || cs2 == null) {
        return false;
    }

    // 3. Length check: if lengths differ, they can't be equal.
    // This is a critical and efficient short-circuit.
    if (cs1.length() != cs2.length()) {
        return false;
    }

    // 4. Optimization for the common String case, which is highly optimized.
    if (cs1 instanceof String && cs2 instanceof String) {
        return cs1.equals(cs2);
    }

    // 5. Fallback to a character-by-character comparison for all other
    // CharSequence types (e.g., StringBuilder, StringBuffer, CharBuffer).
    final int length = cs1.length();
    for (int i = 0; i < length; i++) {
        if (cs1.charAt(i) != cs2.charAt(i)) {
            return false;
        }
    }

    return true;
}

@Override
public int translate(CharSequence input, int index, Writer out) throws IOException {
    // Robustness: Perform null checks on inputs.
    if (input == null || out == null) {
        return 0;
    }

    int seqEnd = input.length();

    // Logic: Check for the "&#" prefix and ensure there's enough length for a minimal entity (e.g., "&#1;").
    if (input.charAt(index) == '&' && index < seqEnd - 3 && input.charAt(index + 1) == '#') {
        int start = index + 2;
        boolean isHex = false;

        char firstChar = input.charAt(start);
        if (firstChar == 'x' || firstChar == 'X') {
            start++;
            isHex = true;
        }

        // Robustness: Ensure there is at least one digit to parse.
        if (start >= seqEnd) {
            return 0; // Handles cases like "&#" or "&#x" at the end of the input.
        }

        int end = start;
        // Logic (Fix): Add a boundary check to the loop to prevent IndexOutOfBoundsException.
        while (end < seqEnd && input.charAt(end) != ';') {
            end++;
        }

        // Logic: Ensure the entity is properly terminated with a semicolon.
        if (end == seqEnd || input.charAt(end) != ';') {
            return 0;
        }

        // Robustness: Ensure the numeric part is not empty (e.g., "&#;" or "&#x;").
        if (start == end) {
            return 0;
        }

        try {
            int entityValue;
            if (isHex) {
                entityValue = Integer.parseInt(input.subSequence(start, end).toString(), 16);
            } else {
                entityValue = Integer.parseInt(input.subSequence(start, end).toString(), 10);
            }

            // Write the character(s) to the output writer.
            // Character.toChars handles supplementary characters (codepoints > 0xFFFF) correctly.
            out.write(Character.toChars(entityValue));

            // Logic (Fix): Return the total number of characters consumed from the input.
            return (end - index) + 1;

        } catch (NumberFormatException nfe) {
            // Robustness (Fix): Fail silently by returning 0 instead of printing to System.err.
            return 0;
        }
    }
    return 0;
}

public static String join(Object[] array, String separator, int startIndex, int endIndex) {
        // 1. Handle null array input
        if (array == null) {
            return null;
        }

        // 2. Add robust boundary checks for startIndex and endIndex
        if (startIndex < 0) {
            throw new IndexOutOfBoundsException("startIndex must not be negative: " + startIndex);
        }
        if (endIndex > array.length) {
            throw new IndexOutOfBoundsException("endIndex cannot be greater than the array length: " + endIndex + " > " + array.length);
        }

        // 3. Handle empty or invalid range
        int noOfItems = endIndex - startIndex;
        if (noOfItems <= 0) {
            return EMPTY;
        }

        // 4. Handle null separator
        if (separator == null) {
            separator = EMPTY;
        }

        // 5. Correct the StringBuilder initial capacity calculation to better estimate the final size,
        //    preventing multiple internal array re-allocations.
        int firstElementLength = (array[startIndex] == null ? 16 : array[startIndex].toString().length());
        int estimatedSize = (firstElementLength + separator.length()) * noOfItems;
        StringBuilder buf = new StringBuilder(estimatedSize);

        // 6. Build the string
        for (int i = startIndex; i < endIndex; i++) {
            if (i > startIndex) {
                buf.append(separator);
            }
            if (array[i] != null) {
                // The append(Object) method safely handles calling toString()
                buf.append(array[i]);
            }
        }
        return buf.toString();
    }

public static boolean isSameLocalTime(Calendar cal1, Calendar cal2) {
        if (cal1 == null || cal2 == null) {
            throw new IllegalArgumentException("The date must not be null");
        }
        // The core logic is to compare each significant field that defines a local date-time.
        // Using HOUR_OF_DAY (0-23) is critical to avoid ambiguity between AM and PM.
        return (cal1.get(Calendar.MILLISECOND) == cal2.get(Calendar.MILLISECOND) &&
                cal1.get(Calendar.SECOND) == cal2.get(Calendar.SECOND) &&
                cal1.get(Calendar.MINUTE) == cal2.get(Calendar.MINUTE) &&
                cal1.get(Calendar.HOUR_OF_DAY) == cal2.get(Calendar.HOUR_OF_DAY) && // Corrected from HOUR
                cal1.get(Calendar.DAY_OF_YEAR) == cal2.get(Calendar.DAY_OF_YEAR) &&
                cal1.get(Calendar.YEAR) == cal2.get(Calendar.YEAR) &&
                cal1.get(Calendar.ERA) == cal2.get(Calendar.ERA) &&
                cal1.getClass() == cal2.getClass());
    }

public static boolean isNumber(String str) {
        if (StringUtils.isEmpty(str)) {
            return false;
        }

        char[] chars = str.toCharArray();
        int len = chars.length;
        int i = 0;
        boolean foundDigit = false;
        boolean hasExponent = false;
        boolean hasDecimalPoint = false;

        // 1. Handle optional leading sign
        if (chars[0] == '+' || chars[0] == '-') {
            if (len == 1) {
                return false; // A lone sign is not a number
            }
            i = 1;
        }

        // 2. Handle hexadecimal format (which is a distinct path)
        if (len > i + 1 && chars[i] == '0' && (chars[i + 1] == 'x' || chars[i + 1] == 'X')) {
            i += 2;
            if (i == len) {
                return false; // "0x" or "-0x" is not a number
            }
            for (; i < len; i++) {
                char c = chars[i];
                if (!((c >= '0' && c <= '9') || (c >= 'a' && c <= 'f') || (c >= 'A' && c <= 'F'))) {
                    return false; // Invalid character in hex number
                }
            }
            return true; // Valid hexadecimal integer
        }

        // 3. Process the main body of a decimal, float, or scientific number
        for (; i < len; i++) {
            char c = chars[i];

            if (c >= '0' && c <= '9') {
                foundDigit = true;
            } else if (c == '.') {
                if (hasDecimalPoint || hasExponent) {
                    return false; // Disallow multiple decimals or decimals in exponent
                }
                hasDecimalPoint = true;
            } else if (c == 'e' || c == 'E') {
                if (hasExponent || !foundDigit) {
                    return false; // Disallow multiple exponents or exponent without preceding digits
                }
                hasExponent = true;
                foundDigit = false; // A digit is required after the exponent
                // Allow an optional sign after the exponent
                if (i + 1 < len && (chars[i + 1] == '+' || chars[i + 1] == '-')) {
                    i++; // Consume the sign character
                }
            } else if (c == 'l' || c == 'L') {
                // 'L' suffix is valid only at the end for an integer number
                return i == len - 1 && foundDigit && !hasDecimalPoint && !hasExponent;
            } else if (c == 'f' || c == 'F' || c == 'd' || c == 'D') {
                // 'f'/'d' suffix is valid only at the end of a number with digits
                return i == len - 1 && foundDigit;
            } else {
                // Any other character is invalid
                return false;
            }
        }

        // 4. Final validation: a number must contain at least one digit.
        // This check correctly invalidates strings like ".", "+.", "1e", and "1e-".
        return foundDigit;
    }

public String format(Date date) {
    // 1. Add explicit null check for robustness and clear error reporting.
    if (date == null) {
