}

public static Number createNumber(final String str) throws NumberFormatException {
    if (str == null) {
        return null;
    }
    if (StringUtils.isBlank(str)) {
        throw new NumberFormatException("A blank string is not a valid number");
    }

    // Handle hexadecimal format (more comprehensive check)
    if (str.startsWith("0x") || str.startsWith("-0x") || str.startsWith("0X") || str.startsWith("-0X")) {
        return createInteger(str);
    }

    // Reject clearly invalid formats early for robustness and clarity
    if (str.startsWith("--") || str.endsWith("-") || str.endsWith("+")) {
        throw new NumberFormatException("'" + str + "' is not a valid number.");
    }

    char lastChar = str.charAt(str.length() - 1);

    // Check for type qualifiers (L, F, D)
    if (Character.isLetter(lastChar)) {
        String numberPart = str.substring(0, str.length() - 1);
        boolean isDecimal = numberPart.indexOf('.') != -1 || numberPart.indexOf('e') != -1 || numberPart.indexOf('E') != -1;

        switch (lastChar) {
            case 'l':
            case 'L':
                // A long cannot have a decimal or exponent. Also reject empty/sign-only strings.
                if (isDecimal || numberPart.isEmpty() || (numberPart.charAt(0) == '+' || numberPart.charAt(0) == '-') && numberPart.length() == 1) {
                    throw new NumberFormatException("'" + str + "' is not a valid long.");
                }
                try {
                    // Attempt to parse as Long first
                    return createLong(numberPart);
                } catch (final NumberFormatException nfe) {
                    // If it's too large for a Long, parse as BigInteger
                    return createBigInteger(numberPart);
                }

            case 'f':
            case 'F':
                try {
                    Float f = createFloat(numberPart);
                    // Check for overflow (infinity) and underflow (value becomes 0 when it shouldn't)
                    if (!f.isInfinite() && !(f.floatValue() == 0.0F && new BigDecimal(numberPart).signum() != 0)) {
                        return f;
                    }
                } catch (final NumberFormatException nfe) {
                    // Fall through if parsing fails or number is not suitable
                }
                // FALL-THROUGH: If Float is not suitable, try Double.
            case 'd':
            case 'D':
                try {
                    Double d = createDouble(numberPart);
                    // Check for overflow (infinity) and underflow (value becomes 0 when it shouldn't)
                    if (!d.isInfinite() && !(d.doubleValue() == 0.0D && new BigDecimal(numberPart).signum() != 0)) {
                        return d;
                    }
                } catch (final NumberFormatException nfe) {
                    // Fall through if parsing fails or number is not suitable
                }
                // FALL-THROUGH: If Double is also not suitable, use BigDecimal for maximum precision.
                try {
                    return createBigDecimal(numberPart);
                } catch (final NumberFormatException e) {
                    // If even BigDecimal fails, the original string was malformed.
                    throw new NumberFormatException("'" + str + "' is not a valid number.");
                }
            default:
                // Invalid type qualifier
                throw new NumberFormatException("'" + str + "' is not a valid number.");
        }
    }

    // No type qualifier, so infer the best type
    boolean isDecimal = str.indexOf('.') != -1 || Math.max(str.indexOf('e'), str.indexOf('E')) > -1;

    if (!isDecimal) {
        // It appears to be an integer type
        try {
            return createInteger(str);
        } catch (final NumberFormatException nfe1) {
            try {
                return createLong(str);
            } catch (final NumberFormatException nfe2) {
                // This can still throw a NumberFormatException for invalid formats like "1-2"
                return createBigInteger(str);
            }
        }
    }

    // It's a floating-point type; try Float, then Double, then BigDecimal
    try {
        Float f = createFloat(str);
        if (!f.isInfinite() && !(f.floatValue() == 0.0F && new BigDecimal(str).signum() != 0)) {
            return f;
        }
    } catch (final NumberFormatException nfe) {
        // ignore and try the next type
    }

    try {
        Double d = createDouble(str);
        if (!d.isInfinite() && !(d.doubleValue() == 0.0D && new BigDecimal(str).signum() != 0)) {
            return d;
        }
    } catch (final NumberFormatException nfe) {
        // ignore and try the next type
    }

    // Final fallback to BigDecimal for maximum precision or size
    return createBigDecimal(str);
}

