        // 3. Check for the optional hexadecimal indicator 'x' or 'X'.
        char firstChar = input.charAt(start);
        if (firstChar == 'x' || firstChar == 'X') {
            start++;
            isHex = true;
        }

        // 4. Find the terminating semicolon, ensuring the search stays within bounds.
        int end = start;
        while (end < input.length() && input.charAt(end) != ';') {
            end++;
        }

        // 5. Verify that a semicolon was actually found and that the numeric part is not empty.
        // If the loop finished because it hit the end of input, or if there are no digits
        // (e.g., "&#;" or "&#x;"), then it's not a valid entity.
        if (end == input.length() || start == end) {
            return 0;
        }

        try {
            // 6. Parse the numeric value from the subsequence.
            int entityValue;
            CharSequence numericPart = input.subSequence(start, end);
            if (isHex) {
                entityValue = Integer.parseInt(numericPart.toString(), 16);
            } else {
                entityValue = Integer.parseInt(numericPart.toString(), 10);
            }

            // 7. Write the corresponding Unicode character(s) to the output.
            // The write(int) method correctly handles supplementary characters (code points > 0xFFFF).
            out.write(entityValue);

            // 8. Return the total number of characters consumed. This is the length from the
            // start of the entity ('&') to its end (';'), inclusive.
            return (end + 1) - index;

        } catch (NumberFormatException nfe) {
            // This occurs if the numeric part contains invalid characters (e.g., "&#12a;").
            return 0;
        }
    }

    // The sequence at the current index is not a numeric entity.
    return 0;
}

public static Number createNumber(final String str) throws NumberFormatException {
        if (str == null) {
            return null;
        }
        if (StringUtils.isBlank(str)) {
            throw new NumberFormatException("A blank string is not a valid number");
        }

        // Section 1: Handle hexadecimal numbers (e.g., 0x, #)
        final String[] hexPrefixes = {"0x", "0X", "-0x", "-0X", "#", "-#"};
        int pfxLen = 0;
        for (final String pfx : hexPrefixes) {
            if (str.startsWith(pfx)) {
                pfxLen = pfx.length();
                break;
            }
        }

        if (pfxLen > 0) {
            final int hexDigits = str.length() - pfxLen;
            if (hexDigits > 16) { // A Long is 16 hex digits
                return createBigInteger(str);
            }
            if (hexDigits > 8) { // An Integer is 8 hex digits
                return createLong(str);
            }
            return createInteger(str);
        }

        // Section 2: Handle standard decimal/scientific notation
        final char lastChar = str.charAt(str.length() - 1);
        final int decPos = str.indexOf('.');
        final int expPos = Math.max(str.indexOf('e'), str.indexOf('E'));

        // Validate format: exponent must be after decimal and not at the very end
        if (expPos > -1 && (expPos < decPos || expPos == str.length() - 1)) {
            throw new NumberFormatException(str + " is not a valid number.");
        }

        // Section 3: Handle numbers with type qualifiers (L, F, D)
        if (!Character.isDigit(lastChar) && lastChar != '.') {
            final String numeric = str.substring(0, str.length() - 1);
            final String mant = decPos > -1 ? numeric.substring(0, decPos) : numeric;
            final String exp = expPos > -1 ? numeric.substring(expPos + 1) : null;
            final boolean allZeros = isAllZeros(mant) && isAllZeros(exp);

            switch (lastChar) {
                case 'l':
                case 'L':
                    if (decPos > -1 || expPos > -1) {
                        throw new NumberFormatException(str + " is not a valid number.");
                    }
                    try {
                        return createLong(numeric);
                    } catch (final NumberFormatException e) {
                        return createBigInteger(numeric);
                    }

                case 'f':
                case 'F':
                    try {
                        final Float f = createFloat(numeric);
                        if (!(f.isInfinite() || (f.floatValue() == 0.0F && !allZeros))) {
                            return f;
                        }
                    } catch (final NumberFormatException e) {
                        // Fall through if parsing fails
                    }
                    // Fall through to Double, then BigDecimal for more precision

                case 'd':
                case 'D':
                    try {
                        final Double d = createDouble(numeric);
                        if (!(d.isInfinite() || (d.doubleValue() == 0.0D && !allZeros))) {
                            return d;
                        }
                    } catch (final NumberFormatException e) {
                        // Fall through if parsing fails
                    }
                    try {
                        return createBigDecimal(numeric);
                    } catch (final NumberFormatException e) {
                        throw new NumberFormatException(str + " is not a valid number.");
                    }

                default:
                    throw new NumberFormatException(str + " is not a valid number.");
            }
        }

        // Section 4: Auto-detect type for numbers without qualifiers
        if (decPos == -1 && expPos == -1) {
            // Integral number: try Integer -> Long -> BigInteger
            try {
                return createInteger(str);
            } catch (final NumberFormatException e) { /* ignore */ }
            try {
                return createLong(str);
            } catch (final NumberFormatException e) { /* ignore */ }
            return createBigInteger(str);
        }

        // Floating-point number: try Float -> Double -> BigDecimal
        final String mant = decPos > -1 ? str.substring(0, decPos) : str.substring(0, expPos);
        final String exp = expPos > -1 ? str.substring(expPos + 1) : null;
        final boolean allZeros = isAllZeros(mant) && isAllZeros(exp);

        try {
            final Float f = createFloat(str);
            if (!(f.isInfinite() || (f.floatValue() == 0.0F && !allZeros))) {
                return f;
            }
        } catch (final NumberFormatException e) { /* ignore */ }
        try {
            final Double d = createDouble(str);
            if (!(d.isInfinite() || (d.doubleValue() == 0.0D && !allZeros))) {
                return d;
            }
        } catch (final NumberFormatException e) { /* ignore */ }

        return createBigDecimal(str);
    }

public static int indexOfAny(String str, String[] searchStrs) {
    if (str == null || searchStrs == null) {
        return INDEX_NOT_FOUND;
    }

    int sz = searchStrs.length;
    // Initialize to a value that indicates "not found yet"
    int ret = Integer.MAX_VALUE;

    int tmp;
    for (int i = 0; i < sz; i++) {
        String search = searchStrs[i];
        if (search == null) {
            continue;
        }
        tmp = str.indexOf(search);
        if (tmp == INDEX_NOT_FOUND) {
            continue;
        }

        // If this match is earlier than the current best, update it.
        if (tmp < ret) {
            ret = tmp;
            // Optimization: if a match is found at index 0,
            // no other match can be earlier, so we can stop searching.
            if (ret == 0) {
                break;
            }
        }
    }

    return (ret == Integer.MAX_VALUE) ? INDEX_NOT_FOUND : ret;
}

public static int indexOfAny(CharSequence cs, char[] searchChars) {
    if (isEmpty(cs) || ArrayUtils.isEmpty(searchChars)) {
        return INDEX_NOT_FOUND;
    }

    // Use a HashSet for O(1) average-time complexity lookups.
    // This is more efficient than iterating the searchChars array for each character in cs.
    final Set<Character> searchCharSet = new HashSet<>();
    for (final char ch : searchChars) {
        searchCharSet.add(ch);
    }

    final int csLen = cs.length();
    for (int i = 0; i < csLen; i++) {
        // Check if the character at the current position is in our set of search characters.
        if (searchCharSet.contains(cs.charAt(i))) {
            return i;
        }
    }

    return INDEX_NOT_FOUND;
}

public static int indexOfAnyBut(CharSequence cs, char[] searchChars) {
    // 1. Handle null or empty CharSequence first.
    if (isEmpty(cs)) {
        return INDEX_NOT_FOUND;
    }
    // 2. Correctly handle null or empty searchChars. If the set of characters
    // to avoid is empty, the first character of cs is the answer.
    if (ArrayUtils.isEmpty(searchChars)) {
        return 0;
    }

    // 3. For performance, load search characters into a HashSet for O(1) average-time lookups.
    final Set<Character> searchCharsSet = new HashSet<>();
    for (final char ch : searchChars) {
        searchCharsSet.add(ch);
    }

    // 4. Iterate through the CharSequence and check for presence in the set.
    final int csLen = cs.length();
    for (int i = 0; i < csLen; i++) {
        // If the character is NOT in the set, we have found our match.
        if (!searchCharsSet.contains(cs.charAt(i))) {
            return i;
        }
    }

    // 5. If the loop completes, all characters in cs were in searchChars.
    return INDEX_NOT_FOUND;
}

public static boolean containsAny(CharSequence cs, char[] searchChars) {
        if (isEmpty(cs) || ArrayUtils.isEmpty(searchChars)) {
            return false;
        }

        final int csLength = cs.length();
        final int searchLength = searchChars.length;

        // Iterate through the input sequence by code points to correctly handle
        // supplementary Unicode characters.
        int i = 0;
        while (i < csLength) {
            final int codePoint = Character.codePointAt(cs, i);

            // A supplementary code point (> 0xFFFF) cannot exist in a char[],
            // so we only need to perform the search if the code point is in the
            // Basic Multilingual Plane (BMP).
            if (Character.isBmpCodePoint(codePoint)) {
                final char ch = (char) codePoint;
                for (int j = 0; j < searchLength; j++) {
                    if (searchChars[j] == ch) {
                        return true;
                    }
                }
            }

            // Advance the index by the number of chars used by the current code point
            // (1 for BMP, 2 for supplementary).
            i += Character.charCount(codePoint);
        }

        return false;
    }

public static int indexOfAnyBut(String str, String searchChars) {
        // 1. Handle null or empty input string: Nothing to search.
        if (isEmpty(str)) {
            return INDEX_NOT_FOUND;
        }
        // 2. Handle null or empty search characters (Corrected Logic):
        // If searchChars is empty, any character in str is a valid result.
        // Return the first index.
        if (isEmpty(searchChars)) {
            return 0;
        }

        // 3. Improve performance by using a Set for O(1) average-time lookups.
        // This avoids the O(N*M) complexity of the original implementation.
        // The cost is O(M) to build the set, where M is the length of searchChars.
        final int searchLen = searchChars.length();
        final Set<Character> searchSet = new HashSet<>(searchLen);
        for (int i = 0; i < searchLen; i++) {
            searchSet.add(searchChars.charAt(i));
        }

        // 4. Iterate through the input string.
        // The cost is O(N), where N is the length of str.
        final int strLen = str.length();
        for (int i = 0; i < strLen; i++) {
            // If the character is NOT in the search set, we've found our match.
            if (!searchSet.contains(str.charAt(i))) {
                return i;
            }
        }

        // 5. If the loop completes, all characters in str were found in searchChars.
        return INDEX_NOT_FOUND;
    }

public static Class<?>[] toClass(Object[] array) {
    if (array == null) {
        return null;
    }
    if (array.length == 0) {
        return ArrayUtils.EMPTY_CLASS_ARRAY;
    }
    Class<?>[] classes = new Class[array.length];
    for (int i = 0; i < array.length; i++) {
        // Add a null-check for each element in the array.
        // If an element is null, the corresponding Class in the output array will also be null.
        classes[i] = (array[i] == null) ? null : array[i].getClass();
    }
    return classes;
}

public static boolean containsNone(final CharSequence cs, final char[] searchChars) {
    if (cs == null || searchChars == null) {
        return true;
    }
    final int csLength = cs.length();
    final int searchLength = searchChars.length;
    if (csLength == 0 || searchLength == 0) {
        return true;
    }

    // Create a set of code points for efficient O(1) average time complexity lookups.
    // Since the search input is a char[], each element is treated as a
    // distinct Basic Multilingual Plane (BMP) code point.
    final Set<Integer> searchCodePoints = new HashSet<>(searchLength);
    for (final char ch : searchChars) {
        searchCodePoints.add((int) ch);
    }

    // Iterate through the input CharSequence by code points to correctly handle
    // supplementary characters (e.g., emojis).
    for (int i = 0; i < csLength; ) {
        final int codePoint = Character.codePointAt(cs, i);
        if (searchCodePoints.contains(codePoint)) {
            // A code point from the input string was found in the set of invalid characters.
            // This check correctly compares whole code points and will not match a
            // supplementary character against a lone surrogate in the search set.
            return false;
        }
        // Advance the index by the number of chars used by the current code point (1 for BMP, 2 for supplementary).
        i += Character.charCount(codePoint);
    }

    return true;
}

public static <T> T[] add(T[] array, int index, T element) {
        final int length = (array == null) ? 0 : array.length;

        // 1. Add robust index validation.
        if (index < 0 || index > length) {
            throw new IndexOutOfBoundsException("Index: " + index + ", Length: " + length);
        }

        Class<?> clss;
        if (array != null) {
            clss = array.getClass().getComponentType();
        } else if (element != null) {
            clss = element.getClass();
        } else {
            // 2. Fix the critical bug by throwing an exception instead of returning a
            // value that will cause a ClassCastException.
            throw new IllegalArgumentException("Cannot determine array type: both array and element are null.");
        }

        // 3. Implement the array creation and copy logic.
        @SuppressWarnings("unchecked")
        final T[] newArray = (T[]) Array.newInstance(clss, length + 1);

        if (array != null) {
            // Copy elements from the original array to the new array.
            // Copy elements before the insertion point.
            System.arraycopy(array, 0, newArray, 0, index);
            // Copy elements after the insertion point.
            System.arraycopy(array, index, newArray, index + 1, length - index);
        }

        newArray[index] = element;

        return newArray;
    }

public static <T> T[] add(T[] array, T element) {
        Class<?> type;
        if (array != null) {
            // Correctly get the component type of the array (e.g., String.class from String[]).
            type = array.getClass().getComponentType();
        } else if (element != null) {
            // If the array is null, infer the type from the element.
            type = element.getClass();
        } else {
            // If both are null, we can't infer a specific type, so we default to Object.
            // This will result in an Object[] being returned, which is the only safe assumption.
            type = Object.class;
        }

        // The copyArrayGrow1 method is assumed to handle the allocation and copy.
        @SuppressWarnings("unchecked") // The new array is created from the component type, so the cast is safe.
        T[] newArray = (T[]) copyArrayGrow1(array, type);

        // Add the new element to the end of the new array.
        newArray[newArray.length - 1] = element;

        return newArray;
    }

public static Number createNumber(final String str) throws NumberFormatException {
        if (str == null) {
            return null;
        }
        if (StringUtils.isBlank(str)) {
            throw new NumberFormatException("A blank string is not a valid number");
        }
        if (str.startsWith("--")) {
            // Reject malformed input consistently by throwing an exception.
            throw new NumberFormatException("String value '" + str + "' has multiple sign characters and is not a valid number");
        }
        if (str.startsWith("0x") || str.startsWith("-0x")) {
            return createInteger(str);
        }

        final char lastChar = str.charAt(str.length() - 1);

        final int decPos = str.indexOf('.');
        // Corrected, robust, and readable way to find the exponent position.
        final int expPos = Math.max(str.indexOf('e'), str.indexOf('E'));

        // Early validation for malformed number structure.
        if (expPos > -1 && expPos < decPos) {
            throw new NumberFormatException("'" + str + "' is not a valid number: exponent separator 'e'/'E' cannot appear before decimal point '.'");
        }

        String mant;
        String exp;
        if (decPos > -1) {
            mant = str.substring(0, decPos);
        } else {
            mant = (expPos > -1) ? str.substring(0, expPos) : str;
        }

        if (!Character.isDigit(lastChar)) {
            // The string ends with a type qualifier (e.g., 'L', 'F', 'D').
            final String numeric = str.substring(0, str.length() - 1);
            if (expPos > -1 && expPos < str.length() - 1) {
                exp = str.substring(expPos + 1, str.length() - 1);
            } else {
                exp = null;
            }
            final boolean allZeros = isAllZeros(mant) && isAllZeros(exp);

            switch (lastChar) {
                case 'l':
                case 'L':
                    if (decPos == -1 && expPos == -1 && (numeric.charAt(0) == '-' ? isDigits(numeric.substring(1)) : isDigits(numeric))) {
                        try {
                            return createLong(numeric);
                        } catch (final NumberFormatException nfe) {
                            // Value is too large for a Long, fall back to BigInteger.
                            return createBigInteger(numeric);
                        }
                    }
                    throw new NumberFormatException("'" + str + "' is not a valid number.");
                case 'f':
                case 'F':
                    try {
                        final Float f = createFloat(numeric);
                        if (!f.isInfinite() && (f.floatValue() != 0.0F || allZeros)) {
                            return f;
                        }
                    } catch (final NumberFormatException nfe) {
                        // Ignore and fall through to try Double/BigDecimal.
                    }
                    // FALL-THROUGH (intentional)
                case 'd':
                case 'D':
                    try {
                        final Double d = createDouble(numeric);
                        // Corrected: use doubleValue() for the check.
                        if (!d.isInfinite() && (d.doubleValue() != 0.0D || allZeros)) {
                            return d;
                        }
                    } catch (final NumberFormatException nfe) {
                        // Ignore and fall through to try BigDecimal.
                    }
                    try {
                        return createBigDecimal(numeric);
                    } catch (final NumberFormatException e) {
                        // This will be caught by the default case.
                    }
                    // FALL-THROUGH (intentional)
                default:
                    throw new NumberFormatException("'" + str + "' is not a valid number.");
            }
        } else {
            // No type qualifier; auto-detect the best type.
            if (expPos > -1 && expPos < str.length()) {
                exp = str.substring(expPos + 1);
            } else {
                exp = null;
            }

            if (decPos == -1 && expPos == -1) {
                // It's an integer-like number. Try to fit into the smallest possible type.
                try {
                    return createInteger(str);
                } catch (final NumberFormatException nfe) {
                    // ignore
                }
                try {
                    return createLong(str);
                } catch (final NumberFormatException nfe) {
                    // ignore
                }
                return createBigInteger(str); // May throw if not a valid BigInteger.
            } else {
                // It's a decimal-like number. Try to fit into the smallest type without losing precision.
                final boolean allZeros = isAllZeros(mant) && isAllZeros(exp);
                try {
                    final Float f = createFloat(str);
                    if (!f.isInfinite() && (f.floatValue() != 0.0F || allZeros)) {
                        return f;
                    }
                } catch (final NumberFormatException nfe) {
                    // ignore
                }
                try {
                    final Double d = createDouble(str);
                    if (!d.isInfinite() && (d.doubleValue() != 0.0D || allZeros)) {
                        return d;
                    }
                } catch (final NumberFormatException nfe) {
                    // ignore
                }
                return createBigDecimal(str); // Fallback for full precision.
            }
        }
    }

public static boolean isNumber(String str) {
    if (str == null || str.isEmpty()) {
        return false;
    }

    char[] chars = str.toCharArray();
    int len = chars.length;
    int i = 0;
    boolean hasDigit = false;
    boolean hasExp = false;
    boolean hasDecPoint = false;

    // 1. Handle optional leading sign
    if (chars[i] == '+' || chars[i] == '-') {
        i++;
    }

    // A string with only a sign is not a number
    if (i == len) {
        return false;
    }

    // 2. Handle hexadecimal format (which is mutually exclusive with other formats)
    if (len > i + 1 && chars[i] == '0' && (chars[i + 1] == 'x' || chars[i + 1] == 'X')) {
        i += 2;
        // Hex numbers must have at least one hex digit
        if (i == len) {
            return false; // e.g., "0x", "-0x"
        }
        // The rest must be hex digits, with an optional 'L' suffix
        for (; i < len; i++) {
            char c = chars[i];
            boolean isHexDigit = (c >= '0' && c <= '9') || (c >= 'a' && c <= 'f') || (c >= 'A' && c <= 'F');
            // The 'L' suffix is only allowed as the very last character
            boolean isLastCharL = (c == 'l' || c == 'L') && (i == len - 1);

            if (!isHexDigit && !isLastCharL) {
                return false;
            }
        }
        return true;
    }

    // 3. Handle standard decimal/scientific numbers
    int end = len;
    char lastChar = chars[len - 1];

    // Check for and temporarily ignore a final type qualifier
    if (lastChar == 'f' || lastChar == 'F' || lastChar == 'd' || lastChar == 'D' || lastChar == 'l' || lastChar == 'L') {
        end--;
    }

    // Loop through the main body of the number string
    while (i < end) {
        char c = chars[i];
        if (c >= '0' && c <= '9') {
            hasDigit = true;
        } else if (c == '.') {
            if (hasDecPoint || hasExp) {
                return false; // Disallow multiple decimal points or a point in the exponent
            }
            hasDecPoint = true;
        } else if (c == 'e' || c == 'E') {
            if (hasExp || !hasDigit) {
                return false; // Disallow multiple exponents or an exponent without a preceding digit
            }
            hasExp = true;
            // An exponent may be followed by an optional sign
            if (i + 1 < end && (chars[i + 1] == '+' || chars[i + 1] == '-')) {
                i++;
            }
            // The exponent (and its optional sign) must be followed by at least one digit
            if (i + 1 >= end) {
                return false;
            }
        } else {
            return false; // Invalid character in the number's body
        }
        i++;
    }

    // After the loop, perform final validation
    if (i < len) { // A type qualifier was present
        // A long qualifier ('l' or 'L') is invalid with a decimal point or exponent
        if ((lastChar == 'l' || lastChar == 'L') && (hasDecPoint || hasExp)) {
            return false;
        }
        // For any qualifier to be valid, at least one digit must have been found
        return hasDigit;
    } else { // No type qualifier was present
        // A valid number must contain at least one digit
        return hasDigit;
    }
}

public StringBuffer format(Calendar calendar, StringBuffer buf) {
    // Fail-fast: Validate that input parameters are not null.
    if (calendar == null) {
        throw new NullPointerException("The calendar parameter cannot be null.");
    }
    if (buf == null) {
        throw new NullPointerException("The buffer parameter cannot be null.");
    }

    // Use a separate variable for the calendar to be formatted.
    // This improves clarity over re-assigning the parameter.
    final Calendar calendarToUse;
    if (mTimeZoneForced) {
        // Clone the calendar to avoid modifying the original instance passed by the caller.
        // This is critical for preventing side effects.
        calendarToUse = (Calendar) calendar.clone();
        calendarToUse.setTimeZone(mTimeZone);
    } else {
        // Use the original calendar instance if no timezone override is forced.
        calendarToUse = calendar;
    }

    // Delegate to the internal method that applies the formatting rules.
    return applyRules(calendarToUse, buf);
}

@Override
    public int translate(final CharSequence input, final int index, final Writer out) throws IOException {
        // 1. Add robust argument validation
        if (out == null) {
            throw new IllegalArgumentException("The Writer must not be null.");
        }
        // A null input or an out-of-bounds index means no translation can occur.
        // Returning 0 is consistent with the method's contract of "zero characters consumed".
        if (input == null || index < 0 || index >= input.length()) {
            return 0;
        }

        // 2. Calculate the maximum possible match length from the current index
        final int maxMatchLength = Math.min(longest, input.length() - index);

        // 3. Perform a greedy search for the longest match
        // The loop descends from the longest possible match to the shortest.
        for (int i = maxMatchLength; i >= shortest; i--) {
            final CharSequence subSeq = input.subSequence(index, index + i);

            // 4. Ensure reliable map lookup by using a String key
            final CharSequence result = lookupMap.get(subSeq.toString());

            if (result != null) {
                out.write(result.toString());
                return i; // Return the number of input characters consumed
            }
        }

        // 5. Return 0 if no match was found
        return 0;
    }

public static String getShortClassName(String className) {
    // 1. Handle null and empty string inputs
    if (className == null || className.length() == 0) {
        // The original code used StringUtils.EMPTY, which is good practice.
        // We will return an empty literal for self-containment.
        return "";
    }

    // 2. Handle array types, both in source-code and JVM internal format
    if (className.endsWith("[]")) {
        StringBuilder arrayBrackets = new StringBuilder();
        while (className.endsWith("[]")) {
            className = className.substring(0, className.length() - 2);
            arrayBrackets.append("[]");
        }
        // Recursively find the short name of the component type and append brackets
        String componentShortName = getShortClassName(className);
        return componentShortName + arrayBrackets;
    }

    // This block handles JVM internal array names like '[Ljava.lang.String;'
    if (className.startsWith("[")) {
        StringBuilder arrayBrackets = new StringBuilder();
        int componentNameStartIndex = 0;
        while (className.charAt(componentNameStartIndex) == '[') {
            componentNameStartIndex++;
            arrayBrackets.append("[]");
        }

        // Check for object array ('[L...') or primitive array ('[I', '[B', etc.)
        char typeChar = className.charAt(componentNameStartIndex);
        String componentTypeName;
        if (typeChar == 'L' && className.endsWith(";")) {
            // It's an object type, e.g., 'Ljava.lang.String;'
            componentTypeName = className.substring(componentNameStartIndex + 1, className.length() - 1);
        } else {
            // It's a primitive type. Use the reverse abbreviation map.
            // The original class context shows an 'abbreviationMap'. We infer a reverse map exists.
            // If not, a switch statement would be used here.
            if (reverseAbbreviationMap.containsKey(String.valueOf(typeChar))) {
                componentTypeName = reverseAbbreviationMap.get(String.valueOf(typeChar));
            } else {
                // Fallback for unknown primitive codes
                componentTypeName = className.substring(componentNameStartIndex);
            }
        }
        // Recursively find the short name and append the brackets
        return getShortClassName(componentTypeName) + arrayBrackets;
    }

    // 3. Handle simple and inner classes (the original logic was mostly correct here)
    int lastDotIdx = className.lastIndexOf(PACKAGE_SEPARATOR_CHAR);
    int innerClassIdx = className.indexOf(INNER_CLASS_SEPARATOR_CHAR, lastDotIdx > -1 ? lastDotIdx + 1 : 0);

    String out = className.substring(lastDotIdx + 1);
    if (innerClassIdx != -1) {
        // Replace the inner class separator '$' with a '.' for readability
        out = out.replace(INNER_CLASS_SEPARATOR_CHAR, PACKAGE_SEPARATOR_CHAR);
    }

    return out;
}

public static String getPackageName(String className) {
        if (StringUtils.isEmpty(className)) {
            return StringUtils.EMPTY;
        }

        // Handle canonical array names (e.g., "java.lang.String[]")
        while (className.endsWith("[]")) {
            className = className.substring(0, className.length() - 2);
        }

        // Handle internal array names (e.g., "[Ljava.lang.String;")
        if (className.startsWith("[")) {
            // Check if it's an object array (e.g., "[Ljava.lang.String;")
            // The class name is between the 'L' and the ';'
            if (className.charAt(className.lastIndexOf('[') + 1) == 'L' && className.endsWith(";")) {
                className = className.substring(className.lastIndexOf('[') + 2, className.length() - 1);
            } else {
                // It's a primitive array (e.g., "[I", "[[Z"), which has no package.
                return StringUtils.EMPTY;
            }
        }

        // At this point, we have a non-array class name.
        // This logic correctly handles binary names of inner classes (e.g., "java.util.Map$Entry")
        // but will incorrectly parse canonical names of inner classes (e.g., "java.util.Map.Entry").
        // This is a well-known limitation of string-based parsing without reflection.
        int lastDotIndex = className.lastIndexOf(PACKAGE_SEPARATOR_CHAR);
        if (lastDotIndex == -1) {
            return StringUtils.EMPTY;
        }

        return className.substring(0, lastDotIndex);
    }

public static Number createNumber(final String val) throws NumberFormatException {
        if (val == null) {
            return null;
        }
        if (val.isEmpty()) {
            throw new NumberFormatException("A blank string is not a valid number");
        }

        // Handle common invalid formats early
        if (val.startsWith("--")) {
            // Rejects "--1", which is not a standard number format
            throw new NumberFormatException("'" + val + "' is not a valid number.");
        }
        if (val.equalsIgnoreCase("-") || val.equalsIgnoreCase("+") || val.equalsIgnoreCase(".")) {
            throw new NumberFormatException("'" + val + "' is not a valid number.");
        }

        // Handle hexadecimal numbers
        if (val.startsWith("0x") || val.startsWith("-0x") || val.startsWith("0X") || val.startsWith("-0X")) {
            try {
                return createInteger(val);
            } catch (final NumberFormatException e) {
                // The number may be too large for an Integer, try Long
                try {
                    return createLong(val);
                } catch (final NumberFormatException e2) {
                    // Re-throw with a more informative message
                    throw new NumberFormatException("'" + val + "' is not a valid hexadecimal number.");
                }
            }
        }

        final char lastChar = val.charAt(val.length() - 1);
        final String numericPart;
        final boolean hasQualifier = Character.isLetter(lastChar) && lastChar != 'e' && lastChar != 'E';

        if (hasQualifier) {
            numericPart = val.substring(0, val.length() - 1);
        } else {
            numericPart = val;
        }

        final boolean hasDecimal = numericPart.indexOf('.') != -1;
        final boolean hasExponent = numericPart.indexOf('e') != -1 || numericPart.indexOf('E') != -1;

        if (!hasQualifier) {
            // No type qualifier, infer the type
            if (hasExponent && numericPart.charAt(numericPart.length() - 1) == 'e' || numericPart.charAt(numericPart.length() - 1) == 'E') {
                throw new NumberFormatException("'" + val + "' is not a valid number.");
            }
            if (!hasDecimal && !hasExponent) {
                // It's an integer
                try {
                    return createInteger(val);
                } catch (final NumberFormatException e) {
                    // Not an Integer
                }
                try {
                    return createLong(val);
                } catch (final NumberFormatException e) {
                    // Not a Long, fall back to BigInteger
                }
                return createBigInteger(val);
            }
            // It's a decimal
            final boolean isAllZeros = isMantissaAllZeros(numericPart);
            try {
                final Float f = createFloat(val);
                if (!(f.isInfinite() || (f.floatValue() == 0.0F && !isAllZeros))) {
                    return f;
                }
            } catch (final NumberFormatException e) {
                // ignore
            }
            try {
                final Double d = createDouble(val);
                if (!(d.isInfinite() || (d.doubleValue() == 0.0D && !isAllZeros))) {
                    return d;
                }
            } catch (final NumberFormatException e) {
                // ignore
            }
            return createBigDecimal(val);
        }

        // Has a type qualifier
        if (hasExponent && numericPart.charAt(numericPart.length() - 1) == 'e' || numericPart.charAt(numericPart.length() - 1) == 'E') {
            throw new NumberFormatException("'" + val + "' is not a valid number.");
        }

        switch (lastChar) {
            case 'l':
            case 'L':
                if (hasDecimal || hasExponent) {
                    throw new NumberFormatException("'" + val + "' is not a valid number.");
                }
                if (!isDigits(numericPart.startsWith("-") ? numericPart.substring(1) : numericPart)) {
                    throw new NumberFormatException("'" + val + "' is not a valid number.");
                }
                try {
                    return createLong(numericPart);
                } catch (final NumberFormatException e) {
                    return createBigInteger(numericPart);
                }
            case 'f':
            case 'F':
                try {
                    final Float f = createFloat(numericPart);
                    if (!(f.isInfinite() || (f.floatValue() == 0.0F && !isMantissaAllZeros(numericPart)))) {
                        return f;
                    }
                } catch (final NumberFormatException e) {
                    // Fall through
                }
            case 'd':
            case 'D':
                try {
                    final Double d = createDouble(numericPart);
                    if (!(d.isInfinite() || (d.doubleValue() == 0.0D && !isMantissaAllZeros(numericPart)))) {
                        return d;
                    }
                } catch (final NumberFormatException e) {
                    // Fall through
                }
                try {
                    return createBigDecimal(numericPart);
                } catch (final NumberFormatException e) {
                    // This is the last resort.
                    throw new NumberFormatException("'" + val + "' is not a valid number.");
                }
            default:
                throw new NumberFormatException("'" + val + "' is not a valid number.");
        }
    }

public static String abbreviate(String str, int lower, int upper, String appendToEnd) {
        // 1. Initial check for null or empty string.
        if (StringUtils.isEmpty(str)) {
            return str;
        }

        // 2. Sanitize the lower bound to be non-negative.
        int lowerBound = Math.max(lower, 0);

        // 3. If the string is already shorter than the minimum length, no abbreviation is possible or needed.
        if (str.length() <= lowerBound) {
            return str;
        }

        // 4. Sanitize the upper bound. A value of -1 means no upper limit.
        int upperBound = upper;
        if (upperBound == -1 || upperBound > str.length()) {
            upperBound = str.length();
        }

        // If the string's length is within the sanitized upper bound, no abbreviation is needed.
        if (upperBound >= str.length()) {
            return str;
        }

        // If the user provided an invalid range, adjust the lower bound to prevent errors.
        // The abbreviation will default to a hard cut at the upper bound.
        if (upperBound < lowerBound) {
            lowerBound = upperBound;
        }

        StringBuilder result = new StringBuilder();

        // 5. Find the best abbreviation point: the last space at or before the upper bound.
        int spaceIndex = str.lastIndexOf(' ', upperBound);

        // 6. If a space is found and it creates a string that meets the lower bound, abbreviate there.
        if (spaceIndex != -1 && spaceIndex >= lowerBound) {
            result.append(str.substring(0, spaceIndex));
        } else {
            // Otherwise, no suitable word boundary was found. Perform a hard truncation at the upper bound.
            result.append(str.substring(0, upperBound));
        }

        // 7. An abbreviation has occurred, so append the suffix.
        result.append(StringUtils.defaultString(appendToEnd));

        return result.toString();
    }

