public StrBuilder appendFixedWidthPadRight(Object obj, int width, char padChar) {
    if (width > 0) {
        ensureCapacity(size + width);
        String str = (obj == null ? getNullText() : obj.toString());
        // Robustness fix: Handle the case where the null text is also null.
        if (str == null) {
            str = "";
        }

        int strLen = str.length();
        if (strLen >= width) {
            // Truncate
            str.getChars(0, width, buffer, size);
        } else {
            // Pad
            int padLen = width - strLen;
            str.getChars(0, strLen, buffer, size);
            for (int i = 0; i < padLen; i++) {
                buffer[size + strLen + i] = padChar;
            }
        }
        size += width;
    }
    return this;
}

public StrBuilder appendFixedWidthPadLeft(Object obj, int width, char padChar) {
    if (width > 0) {
        ensureCapacity(size + width);
        String str = (obj == null ? getNullText() : obj.toString());

        // Robustness Fix: Guard against a non-null object whose toString() returns null.
        if (str == null) {
            str = getNullText();
        }

        int strLen = str.length();
        if (strLen >= width) {
            // String is longer or equal to the desired width, so truncate from the left.
            // This is achieved by copying the last 'width' characters.
            str.getChars(strLen - width, strLen, buffer, size);
        } else {
            // String is shorter than the desired width, so pad on the left.
            int padLen = width - strLen;
            for (int i = 0; i < padLen; i++) {
                buffer[size + i] = padChar;
            }
            // Copy the string's content after the padding.
            str.getChars(0, strLen, buffer, size + padLen);
        }
        // The total length appended is always equal to the width.
        size += width;
    }
    return this;
}

public Fraction reduce() {
    // Handle the zero numerator case for clarity and efficiency.
    // The canonical form of a zero fraction is 0/1.
    if (numerator == 0) {
        return equals(ZERO) ? this : ZERO;
    }

    // The greatestCommonDivisor method requires non-negative inputs.
    // Math.abs(Integer.MIN_VALUE) overflows and returns a negative number,
    // which would cause the GCD calculation to fail. We must handle this edge case.
    if (numerator == Integer.MIN_VALUE) {
        // The only prime factor of |Integer.MIN_VALUE| (2^31) is 2.
        // Therefore, if the denominator is odd, the GCD is 1.
        if ((denominator & 1) == 1) {
            return this; // Already in simplest form.
        }
        // If both numerator and denominator are even, we cannot call the standard GCD algorithm.
        // However, we can create a new fraction by safely dividing both parts by 2 and then
        // recursively calling reduce() on the new fraction. This process will eventually
        // yield a numerator that is no longer MIN_VALUE or a denominator that is odd.
        return Fraction.getFraction(numerator / 2, denominator / 2).reduce();
    }

    // For all other integer values, the original logic is sound.
    final int gcd = greatestCommonDivisor(Math.abs(numerator), denominator);
    if (gcd == 1) {
        return this;
    }

    return Fraction.getFraction(numerator / gcd, denominator / gcd);
}

public static Locale toLocale(final String str) {
        if (str == null) {
            return null;
        }
        final int len = str.length();
        if (len < 2) {
            throw new IllegalArgumentException("Invalid locale format: " + str);
        }
        final char ch0 = str.charAt(0);
        final char ch1 = str.charAt(1);
        if (!Character.isLowerCase(ch0) || !Character.isLowerCase(ch1)) {
            throw new IllegalArgumentException("Invalid locale format: Language code must be two lowercase letters: " + str);
        }

        // Case 1: Language only (e.g., "en")
        if (len == 2) {
            return new Locale(str);
        }

        // After this point, the string must be of the form "ll_..."
        if (str.charAt(2) != '_') {
            throw new IllegalArgumentException("Invalid locale format: Missing underscore after language code: " + str);
        }

        // Case 2: Language and Variant with empty Country (e.g., "fr__POSIX")
        if (len >= 5 && str.charAt(3) == '_') {
            // The variant part must not be empty
            if (len < 5) {
                // This is logically unreachable due to the outer len >= 5 check,
                // but included for clarity.
                throw new IllegalArgumentException("Invalid locale format: Empty variant after '__': " + str);
            }
            return new Locale(str.substring(0, 2), "", str.substring(4));
        }

        // From here, we can have "ll_CC", "ll_CC_variant", or "ll_variant".
        // We check for the most specific format first to resolve ambiguity.

        // Case 3: Language, Country, and Variant (e.g., "en_US_WIN")
        // This is the most specific format with two underscores.
        if (len >= 7 && str.charAt(5) == '_' &&
            Character.isUpperCase(str.charAt(3)) && Character.isUpperCase(str.charAt(4))) {
            // The variant part must not be empty
            if (str.length() == 6) {
                 throw new IllegalArgumentException("Invalid locale format: Empty variant after country code: " + str);
            }
            return new Locale(str.substring(0, 2), str.substring(3, 5), str.substring(6));
        }

        // Case 4: Language and Country (e.g., "en_US")
        if (len == 5 &&
            Character.isUpperCase(str.charAt(3)) && Character.isUpperCase(str.charAt(4))) {
            return new Locale(str.substring(0, 2), str.substring(3, 5));
        }

        // Case 5: Language and Variant (e.g., "de_EURO" or "en_us")
        // This is the fallback for any "ll_..." format that wasn't matched above.
        if (len >= 5) {
            return new Locale(str.substring(0, 2), "", str.substring(3));
        }

        // Any other format is invalid (e.g., "en_", "en_U")
        throw new IllegalArgumentException("Invalid locale format: " + str);
    }

public static synchronized FastDateFormat getDateTimeInstance(int dateStyle, int timeStyle, TimeZone timeZone,
        Locale locale) {

    // 1. Determine the definitive locale to be used, defaulting if the input is null.
    final Locale finalLocale = (locale != null) ? locale : Locale.getDefault();

    // 2. Construct a cache key that accurately reflects ALL parameters used for creation.
    //    Using modern Integer.valueOf() instead of the deprecated constructor.
    Object key = Pair.of(Integer.valueOf(dateStyle), Integer.valueOf(timeStyle));
    if (timeZone != null) {
        key = Pair.of(key, timeZone);
    }
    // Always include the final, non-null locale in the key.
    key = Pair.of(key, finalLocale);

    // The original code assumes cDateTimeInstanceCache is a simple Map, so we retain
    // the synchronized block for thread safety.
    @SuppressWarnings("unchecked") // Assuming the cache is managed correctly
    FastDateFormat format = (FastDateFormat) cDateTimeInstanceCache.get(key);

    if (format == null) {
        try {
            // 3. Use the standard JDK DateFormat to obtain the locale-specific pattern.
            //    The definitive 'finalLocale' is used here.
            SimpleDateFormat formatter =
                    (SimpleDateFormat) DateFormat.getDateTimeInstance(dateStyle, timeStyle, finalLocale);
            String pattern = formatter.toPattern();

            // 4. Create the FastDateFormat instance using the derived pattern and original parameters.
            format = getInstance(pattern, timeZone, finalLocale);

            // 5. Store the new instance in the cache with the correct, comprehensive key.
            cDateTimeInstanceCache.put(key, format);

        } catch (ClassCastException ex) {
            // This can happen if the JRE returns a DateFormat that is not a SimpleDateFormat.
            throw new IllegalArgumentException("No date time pattern for locale: " + finalLocale);
        }
    }
    return format;
}

public static FastDateFormat getDateInstance(int style, TimeZone timeZone, Locale locale) {
        // 1. Validate the style parameter for early failure.
        if (style < FULL || style > SHORT) {
            throw new IllegalArgumentException("Illegal date style: " + style);
        }

        // 2. Resolve the locale to its default if null. This is crucial for creating a
        // canonical cache key and ensuring correct behavior.
        final Locale resolvedLocale = (locale != null) ? locale : Locale.getDefault();

        // 3. Create a composite cache key based on the *actual* parameters that will be
        // used to create the formatter instance.
        Object key = Integer.valueOf(style);
        if (timeZone != null) {
            key = new Pair(key, timeZone);
        }
        key = new Pair(key, resolvedLocale);

        // 4. Use ConcurrentHashMap.computeIfAbsent for high-performance, thread-safe,
        // and atomic caching. The creation lambda is only executed if the key is not present.
        return cDateInstanceCache.computeIfAbsent(key, k -> {
            try {
                // Obtain the standard DateFormat for the given style and resolved locale.
                DateFormat formatter = DateFormat.getDateInstance(style, resolvedLocale);

                // 5. Safely check if the returned formatter is a SimpleDateFormat before casting.
                if (formatter instanceof SimpleDateFormat) {
                    String pattern = ((SimpleDateFormat) formatter).toPattern();
                    // Delegate to the pattern-based factory, which leverages its own cache.
                    return getInstance(pattern, timeZone, resolvedLocale);
                } else {
                    // 6. If not, throw a clear, descriptive exception.
                    throw new UnsupportedOperationException(
                        "The DateFormat provider for locale '" + resolvedLocale +
                        "' returned an instance of " + formatter.getClass().getName() +
                        ", which is not a SimpleDateFormat. Pattern extraction is not supported."
                    );
                }
            } catch (Exception e) {
                // Wrap any exception during creation (e.g., from DateFormat or our own check)
                // into an IllegalArgumentException to signal a problem with the inputs.
                throw new IllegalArgumentException(
                    "Failed to create a date format for style " + style + " and locale " + resolvedLocale, e);
            }
        });
    }

public static boolean toBoolean(String str) {
    // Fast path for the most common case, the interned string "true".
    if (str == "true") {
        return true;
    }
    if (str == null) {
        return false;
    }

    // The switch on length is a performance optimization.
    switch (str.length()) {
        case 2: {
            char ch0 = str.charAt(0);
            char ch1 = str.charAt(1);
            return (ch0 == 'o' || ch0 == 'O') &&
                   (ch1 == 'n' || ch1 == 'N');
        }
        case 3: {
            char ch0 = str.charAt(0);
            char ch1 = str.charAt(1);
            char ch2 = str.charAt(2);
            return (ch0 == 'y' || ch0 == 'Y') &&
                   (ch1 == 'e' || ch1 == 'E') &&
                   (ch2 == 's' || ch2 == 'S');
        }
        case 4: {
            char ch0 = str.charAt(0);
            char ch1 = str.charAt(1);
            char ch2 = str.charAt(2);
            char ch3 = str.charAt(3);
            return (ch0 == 't' || ch0 == 'T') &&
                   (ch1 == 'r' || ch1 == 'R') &&
                   (ch2 == 'u' || ch2 == 'U') &&
                   (ch3 == 'e' || ch3 == 'E');
        }
    }
    return false;
}

public static boolean isAvailableLocale(Locale locale) {
    // 1. Validate input: A null reference cannot be a valid, available locale.
    //    Return false immediately to fulfill the method's contract clearly.
    if (locale == null) {
        return false;
    }

    // 2. Defend against uninitialized state: If the set of available locales
    //    is not initialized, no locale can be considered available. This check
    //    prevents a NullPointerException.
    if (cAvailableLocaleSet == null) {
        // Logging a warning here could be beneficial in a real application
        // to diagnose class initialization issues.
        return false;
    }

    // 3. Perform the lookup only after validation checks have passed.
    return cAvailableLocaleSet.contains(locale);
}

public static Number createNumber(final String str) throws NumberFormatException {
        if (str == null) {
            return null;
        }
        if (StringUtils.isBlank(str)) {
            throw new NumberFormatException("A blank string is not a valid number");
        }
        if (str.startsWith("--")) {
            // BigDecimal constructor accepts this, but it's not a valid number format.
            return null;
        }
        if (str.startsWith("0x") || str.startsWith("-0x")) {
            // Handles hexadecimal integers. Does not support hexadecimal floats (e.g., 0x1.2p3).
            return createInteger(str);
        }

        char lastChar = str.charAt(str.length() - 1);

        // Handle explicit type qualifiers (L, F, D)
        if (Character.isLetter(lastChar) && lastChar != 'e' && lastChar != 'E') {
            String numericPart = str.substring(0, str.length() - 1);
            boolean hasNonZeroDigit = containsNonZeroDigit(numericPart);

            switch (lastChar) {
                case 'l':
                case 'L':
                    // A Long literal cannot have a decimal point or exponent.
                    if (numericPart.indexOf('.') == -1 && numericPart.indexOf('e') == -1 && numericPart.indexOf('E') == -1) {
                        try {
                            return createLong(numericPart);
                        } catch (NumberFormatException nfe) {
                            // The number is too large for a Long, so use BigInteger.
                            return createBigInteger(numericPart);
                        }
                    }
                    throw new NumberFormatException(str + " is not a valid number.");
                case 'f':
                case 'F':
                    try {
                        Float f = createFloat(numericPart);
                        // Avoid returning a float if it overflowed to infinity or underflowed to zero.
                        if (!(f.isInfinite() || (f.floatValue() == 0.0F && hasNonZeroDigit))) {
                            return f;
                        }
                    } catch (NumberFormatException e) {
                        // Fall through to a larger type if Float parsing fails.
                    }
                    // Fall through to Double for more precision/range.
                case 'd':
                case 'D':
                    try {
                        Double d = createDouble(numericPart);
                        // Avoid returning a double if it overflowed or underflowed.
                        if (!(d.isInfinite() || (d.doubleValue() == 0.0D && hasNonZeroDigit))) {
                            return d;
                        }
                    } catch (NumberFormatException e) {
                        // Fall through to BigDecimal if Double parsing fails.
                    }
                    // Fall through to BigDecimal for arbitrary precision.
                default:
                    // This default handles fall-through from 'f' and 'd', and any invalid suffix.
                    try {
                        return createBigDecimal(numericPart);
                    } catch (NumberFormatException e) {
                        // If all attempts fail, the original string is invalid.
                        throw new NumberFormatException(str + " is not a valid number.");
                    }
            }
        }

        // No type qualifier, so auto-detect the best type.
        // A string is considered float-like if it contains '.', 'e', or 'E'.
        final boolean isFloatLike = str.indexOf('.') != -1 || str.indexOf('e') != -1 || str.indexOf('E') != -1;

        if (isFloatLike) {
            boolean hasNonZeroDigit = containsNonZeroDigit(str);
            try {
                Float f = createFloat(str);
                if (!(f.isInfinite() || (f.floatValue() == 0.0F && hasNonZeroDigit))) {
                    return f;
                }
            } catch (NumberFormatException e) {
                // Ignore and try the next larger type.
            }
            try {
                Double d = createDouble(str);
                if (!(d.isInfinite() || (d.doubleValue() == 0.0D && hasNonZeroDigit))) {
                    return d;
                }
            } catch (NumberFormatException e) {
                // Ignore and try the next larger type.
            }
            return createBigDecimal(str); // Final fallback for float-like numbers.
        } else {
            // It's an integer-like number.
            try {
                return createInteger(str);
            } catch (NumberFormatException e) {
                // Ignore and try the next larger type.
            }
            try {
                return createLong(str);
            } catch (NumberFormatException e) {
                // Ignore and try the next larger type.
            }
            return createBigInteger(str); // Final fallback for integer-like numbers.
        }
    }

public synchronized void stop() {
        if (this.runningState != STATE_RUNNING && this.runningState != STATE_SUSPENDED) {
            throw new IllegalStateException("Stopwatch is not running or suspended. Cannot stop.");
        }

        // Capture the timestamp when the stop operation occurs.
        stopTime = System.currentTimeMillis();

        // Transition the primary state to stopped.
        this.runningState = STATE_STOPPED;

        // Reset the split state, as a split is no longer relevant for a stopped watch.
        this.splitState = STATE_UNSPLIT;
    }

public StrBuilder appendFixedWidthPadRight(Object obj, int width, char padChar) {
    if (width > 0) {
        ensureCapacity(size + width);
        final String str = (obj == null ? getNullText() : obj.toString());
        final int strLen = str.length();

        if (strLen >= width) {
            // Truncate the string if it's longer than or equal to the fixed width.
            // Copy only the first 'width' characters.
            str.getChars(0, width, buffer, size);
        } else {
            // The string is shorter, so pad it on the right.
            final int padLen = width - strLen;
            // Copy the string's content.
            str.getChars(0, strLen, buffer, size);
            // Fill the remaining space with the padding character.
            for (int i = 0; i < padLen; i++) {
                buffer[size + strLen + i] = padChar;
            }
        }
        // In both cases (truncation or padding), exactly 'width' characters were added.
        size += width;
    }
    return this;
}

public int indexOf(char ch, int startIndex) {
    // Sanitize the start index. If it's negative, start the search from the beginning.
    startIndex = (startIndex < 0 ? 0 : startIndex);

    // If the sanitized start index is at or beyond the logical size of the builder,
    // the character cannot be found.
    if (startIndex >= size) {
        return -1;
    }

    // Search for the character within the valid range of the buffer.
    // The loop must be bounded by 'size', not 'buffer.length', to avoid
    // searching in the unused capacity of the buffer.
    for (int i = startIndex; i < size; i++) {
        if (buffer[i] == ch) {
            return i; // Character found, return its index.
        }
    }

    // The character was not found in the specified range.
    return -1;
}

public boolean contains(char ch) {
    // The 'size' field tracks the actual number of characters in the StrBuilder.
    // The 'buffer.length' is the capacity, which can be larger than the size.
    // The search must be confined to the valid range of characters, from index 0 to size - 1.
    for (int i = 0; i < this.size; i++) {
        if (this.buffer[i] == ch) {
            return true;
        }
    }
    return false;
}

public int indexOf(String str, int startIndex) {
    // 1. Sanitize startIndex to ensure it is not negative.
    startIndex = Math.max(startIndex, 0);

    // 2. Handle early exit conditions for invalid inputs or impossible searches.
    if (str == null || startIndex >= this.size) {
        return -1;
    }

    int strLen = str.length();

    // 3. An empty string is always "found" at the specified starting index.
    if (strLen == 0) {
        return startIndex;
    }

    // 4. If the search string is longer than the builder's content, it cannot be found.
    if (strLen > this.size) {
        return -1;
    }

    // 5. Optimization: Delegate single-character searches to the specialized method.
    if (strLen == 1) {
        return indexOf(str.charAt(0), startIndex);
    }

    // 6. Calculate the correct maximum starting index for the search.
    // The search must not start at a position where the substring would exceed the content length.
    int maxStartIndex = this.size - strLen;
    char[] thisBuf = this.buffer;

    // 7. Perform the search within the valid content range.
    outer:
    for (int i = startIndex; i <= maxStartIndex; i++) {
        for (int j = 0; j < strLen; j++) {
            // If any character does not match, break the inner loop and continue the outer one.
            if (str.charAt(j) != thisBuf[i + j]) {
                continue outer;
            }
        }
        // If the inner loop completes, all characters matched. Return the starting index.
        return i;
    }

    // 8. If the outer loop completes without finding a match, return -1.
    return -1;
}

public static String formatPeriod(long startMillis, long endMillis, String format, boolean padWithZeros,
                                  TimeZone timezone) {

    // --- ROBUSTNESS: Input Validation ---
    if (format == null) {
        throw new NullPointerException("The format string must not be null.");
    }
    if (startMillis > endMillis) {
        throw new IllegalArgumentException("The startMillis must not be greater than the endMillis.");
    }

    long millis = endMillis - startMillis;
    // Optimization: For durations under 28 days, calendar-aware logic for months/years is not needed.
    if (millis < 28 * (24 * 60 * 60 * 1000L)) { // Assuming DateUtils.MILLIS_PER_DAY
        return formatDuration(millis, format, padWithZeros);
    }

    Token[] tokens = lexx(format);

    Calendar start = Calendar.getInstance(timezone);
    start.setTime(new Date(startMillis));
    Calendar end = Calendar.getInstance(timezone);
    end.setTime(new Date(endMillis));

    // Initial estimates by subtracting fields
    int milliseconds = end.get(Calendar.MILLISECOND) - start.get(Calendar.MILLISECOND);
    int seconds = end.get(Calendar.SECOND) - start.get(Calendar.SECOND);
    int minutes = end.get(Calendar.MINUTE) - start.get(Calendar.MINUTE);
    int hours = end.get(Calendar.HOUR_OF_DAY) - start.get(Calendar.HOUR_OF_DAY);
    int days = end.get(Calendar.DAY_OF_MONTH) - start.get(Calendar.DAY_OF_MONTH);
    int months = end.get(Calendar.MONTH) - start.get(Calendar.MONTH);
    int years = end.get(Calendar.YEAR) - start.get(Calendar.YEAR);

    // --- LOGIC FIX: Correct "Borrowing" ---
    // Adjust each estimate if it's negative by borrowing from the next larger unit.
    while (milliseconds < 0) {
        milliseconds += 1000;
        seconds -= 1;
    }
    while (seconds < 0) {
        seconds += 60;
        minutes -= 1;
    }
    while (minutes < 0) {
        minutes += 60;
        hours -= 1;
    }
    while (hours < 0) {
        hours += 24;
        days -= 1;
    }
    // Correctly borrow from months, using the actual number of days in the relevant month.
    while (days < 0) {
        // Create a temporary calendar to find the days in the month prior to the end date's month.
        Calendar temp = (Calendar) end.clone();
        temp.add(Calendar.MONTH, -1);
        days += temp.getActualMaximum(Calendar.DAY_OF_MONTH);
        months -= 1;
    }
    while (months < 0) {
        months += 12;
        years -= 1;
    }

    // The original 'reduceAndCorrect' calls are assumed to be a final safeguard against
    // edge cases like adding months to Jan 31 and landing on a non-existent Feb 31.
    // With the improved borrowing logic, their necessity is reduced, but we keep them
    // to preserve the original design's intent for handling such overshoots.
    milliseconds -= reduceAndCorrect(start, end, Calendar.MILLISECOND, milliseconds);
    seconds -= reduceAndCorrect(start, end, Calendar.SECOND, seconds);
    minutes -= reduceAndCorrect(start, end, Calendar.MINUTE, minutes);
    hours -= reduceAndCorrect(start, end, Calendar.HOUR_OF_DAY, hours);
    days -= reduceAndCorrect(start, end, Calendar.DAY_OF_MONTH, days);
    months -= reduceAndCorrect(start, end, Calendar.MONTH, months);
    years -= reduceAndCorrect(start, end, Calendar.YEAR, years);

    // --- LOGIC FIX: Correct "Roll-up" of time units ---
    // If a unit is not requested in the format, roll its value into the next smaller unit.
    if (!Token.containsTokenWithValue(tokens, y)) {
        if (Token.containsTokenWithValue(tokens, M)) {
            months += 12 * years;
        } else {
            // Correctly convert years to days, accounting for leap years.
            if (years != 0) {
                Calendar temp = (Calendar) start.clone();
                for (int i = 0; i < years; i++) {
                    days += temp.getActualMaximum(Calendar.DAY_OF_YEAR);
                    temp.add(Calendar.YEAR, 1);
                }
            }
        }
        years = 0;
    }
    if (!Token.containsTokenWithValue(tokens, M)) {
        // If months are not requested, their value must be converted to days.
        // This requires iterating through the months to get the correct day count for each.
        if (months != 0) {
            Calendar temp = (Calendar) start.clone();
            temp.add(Calendar.YEAR, years); // Position at the start of the month block
            for (int i = 0; i < months; i++) {
                days += temp.getActualMaximum(Calendar.DAY_OF_MONTH);
                temp.add(Calendar.MONTH, 1);
            }
        }
        months = 0;
    }
    if (!Token.containsTokenWithValue(tokens, d)) {
        hours += 24 * days;
        days = 0;
    }
    if (!Token.containsTokenWithValue(tokens, H)) {
        minutes += 60 * hours;
        hours = 0;
    }
    if (!Token.containsTokenWithValue(tokens, m)) {
        seconds += 60 * minutes;
        minutes = 0;
    }
    if (!Token.containsTokenWithValue(tokens, s)) {
        milliseconds += 1000 * seconds;
        seconds = 0;
    }

    return format(tokens, years, months, days, hours, minutes, seconds, milliseconds, padWithZeros);
}

@Override
public int compareTo(Object other) {
    // 1. Explicitly check for null input, as recommended by the Comparable contract.
    if (other == null) {
        throw new NullPointerException("Cannot compare ValuedEnum to a null object.");
    }

    // 2. Enforce strict type equality. This prevents comparing different enum
    // types (e.g., Color.RED with Size.LARGE), which is a core principle
    // of the typesafe enum pattern. This check also implicitly handles
    // cases where 'other' is not a ValuedEnum at all.
    if (this.getClass() != other.getClass()) {
        throw new ClassCastException(
            "Cannot compare objects of different enum types: "
            + this.getClass().getName() + " and " + other.getClass().getName());
    }

    // 3. Cast the object now that its type has been verified.
    final ValuedEnum otherEnum = (ValuedEnum) other;

    // 4. Use the standard, safe library method for integer comparison.
    // This avoids the integer overflow/underflow bug found in the original
    // subtraction-based logic.
    return Integer.compare(this.iValue, otherEnum.iValue);
}

public static Number createNumber(final String str) throws NumberFormatException {
    if (str == null) {
        return null;
    }
    if (StringUtils.isBlank(str)) {
        throw new NumberFormatException("A blank string is not a valid number");
    }
    // Handle special cases and prefixes
    if (str.startsWith("--")) {
        // Inconsistent to return null for this invalid format, so throw exception
        throw new NumberFormatException(str + " is not a valid number.");
    }
    if (str.startsWith("0x") || str.startsWith("-0x") || str.startsWith("0X") || str.startsWith("-0X")) {
        // Hexadecimal numbers are always integer types (Integer, Long, or BigInteger)
        // Use a promotion chain with try-catch for robustness with all sizes.
        try {
            return createInteger(str);
        } catch (final NumberFormatException e) {
            // Not an Integer, fall through to try Long
        }
        try {
            return createLong(str);
        } catch (final NumberFormatException e) {
            // Not a Long, fall through to try BigInteger
        }
        return createBigInteger(str);
    }

    final char lastChar = str.charAt(str.length() - 1);
    final String numeric;
    final boolean hasQualifier = !Character.isDigit(lastChar) && lastChar != '.';

    if (hasQualifier) {
        numeric = str.substring(0, str.length() - 1);
    } else {
        numeric = str;
    }

    final boolean isDecimal = numeric.indexOf('.') != -1 || numeric.indexOf('e') != -1 || numeric.indexOf('E') != -1;

    if (!isDecimal) {
        // Integer types (no decimal or exponent)
        if (hasQualifier) {
            // If it has a qualifier, it must be 'L' for a valid integer type
            if (lastChar == 'l' || lastChar == 'L') {
                // Try to create a Long, fallback to BigInteger for very large numbers
                try {
                    return createLong(numeric);
                } catch (final NumberFormatException e) {
                    return createBigInteger(numeric);
                }
            }
            throw new NumberFormatException(str + " is not a valid number.");
        }
        // No qualifier, so auto-detect integer type (Integer -> Long -> BigInteger)
        try {
            return createInteger(numeric);
        } catch (final NumberFormatException e1) {
            try {
                return createLong(numeric);
            } catch (final NumberFormatException e2) {
                return createBigInteger(numeric);
            }
        }
    }

    // Decimal types (contains a decimal or exponent)
    final int expPos = Math.max(numeric.indexOf('e'), numeric.indexOf('E'));

    // Correctly check for all-zero values to handle underflow vs. true zero
    boolean allZeros = false;
    if (expPos > -1) {
        if (expPos < numeric.length() - 1) {
            final String mant = numeric.substring(0, expPos);
            final String dec = mant.indexOf('.') > -1 ? mant.substring(mant.indexOf('.') + 1) : null;
            final String mantInt = mant.indexOf('.') > -1 ? mant.substring(0, mant.indexOf('.')) : mant;
            final String exp = numeric.substring(expPos + 1);
            allZeros = isAllZeros(mantInt) && isAllZeros(dec) && isAllZeros(exp);
        } else {
             throw new NumberFormatException(str + " is not a valid number.");
        }
    } else {
        final String dec = numeric.indexOf('.') > -1 ? numeric.substring(numeric.indexOf('.') + 1) : null;
        final String mantInt = numeric.indexOf('.') > -1 ? numeric.substring(0, numeric.indexOf('.')) : numeric;
        allZeros = isAllZeros(mantInt) && isAllZeros(dec);
    }


    if (hasQualifier) {
        switch (lastChar) {
            case 'f':
            case 'F':
                try {
                    final Float f = createFloat(numeric);
                    // Check for overflow or underflow (loss of precision)
                    if (!(f.isInfinite() || f.floatValue() == 0.0F && !allZeros)) {
                        return f;
                    }
                } catch (final NumberFormatException e) {
                    // Fall through to Double
                }
                // Fall through to Double
            case 'd':
            case 'D':
                try {
                    final Double d = createDouble(numeric);
                    // Check for overflow or underflow (loss of precision)
                    if (!(d.isInfinite() || d.doubleValue() == 0.0D && !allZeros)) {
                        return d;
                    }
                } catch (final NumberFormatException e) {
                    // Fall through to BigDecimal
                }
                // Fall through to BigDecimal
            default: // Includes fall-through from D and invalid qualifiers
                try {
                    return createBigDecimal(numeric);
                } catch (final NumberFormatException e) {
                    throw new NumberFormatException(str + " is not a valid number.");
                }
        }
    }

    // No qualifier, so auto-detect decimal type (Float -> Double -> BigDecimal)
    try {
        final Float f = createFloat(numeric);
        if (!(f.isInfinite() || f.floatValue() == 0.0F && !allZeros)) {
            return f;
        }
    } catch (final NumberFormatException e) {
        // Fall through
    }
    try {
        final Double d = createDouble(numeric);
        if (!(d.isInfinite() || d.doubleValue() == 0.0D && !allZeros)) {
            return d;
        }
    } catch (final NumberFormatException e) {
        // Fall through
    }
    return createBigDecimal(numeric);
}
